(window.GioKinhBooks=window.GioKinhBooks||{})["vo-luong-tho"]={"id":"vo-luong-tho","title":"Kinh Vô Lượng Thọ","by":"Hội tập: Cư sĩ Hạ Liên Cư · Việt dịch: HT Thích Đức Niệm","src":"https://www.daotranglienhoa.com/wp-content/uploads/2022/01/kinh_vo_luong_tho.pdf","srcName":"Đạo Tràng Liên Hoa","chapters":[{"t":"Thay Lời Tựa","b":[["p","Đức Phật ra đời suốt bốn mươi năm trời thuyết pháp, có đến hơn tám vạn bốn ngàn pháp môn. Pháp môn chính là phương pháp mở cửa tuệ giác tâm linh. Chúng sanh căn tánh bất đồng, thiên sai vạn biệt, nên đức Phật cũng theo đó mà có nhiều pháp môn để đáp ứng thích cơ hợp tánh chúng sanh. Tâm bịnh chúng sanh đa dạng, biến thái muôn ngàn, nên pháp dược trị liệu cũng có vạn thiên."],["p","Pháp môn có sai khác, giáo pháp diễn đạt những pháp môn đó có cạn sâu. Nhưng dù sai khác cạn sâu thế nào đi nữa, thì giáo pháp đức Phật tựu trung vẫn là chìa khóa mở cửa tâm linh, những phương thuốc thần diệu trị liệu tâm bịnh chúng sinh, giải thoát phiền khổ. Ngài cũng thuyết minh về những hiện tượng thành hoại của vũ trụ, những sai biệt thăng trầm thạnh suy của kiếp người."],["p","Nhưng cội gốc của những hiện tượng đó đều do tâm sanh khởi. Tâm là nguồn gốc hình thành tất cả mọi hiện tượng, trạng thái thạnh suy, thành bại, thăng trầm của nhân sanh vũ trụ. Thế nên, giáo pháp của đức Phật là chìa khóa mở cửa tâm linh, là phương thuốc trừ sạch gốc rễ vô minh từ tâm thức con người, là con đường sáng ngời đưa chúng sanh từ phàm đến thánh."],["p","Trong tất cả những pháp môn, những phương thuốc, những con đường sáng tịnh đó, được đức Phật trình bày bàn bạc khắp trong tam tạng giáo điển. Nhưng đặc biệt pháp môn Tịnh độ thì đức Phật nhấn mạnh có tánh cách xác quyết với cả tấm lòng tha thiết khuyến lệ chúng sanh nên thực hành pháp môn này. Điều đó hiển lộ qua những thời pháp đặc thù được kết tụ thành kinh A Di Đà, kinh Vô Lượng Thọ, kinh Quán Vô Lượng Thọ, kinh Pháp Hoa, kinh Hoa Nghiêm, kinh Niết Bàn v.v … Chẳng những trong pháp hội kinh A Di Đà Ngài diễn tả cảnh giới Tây phương Cực lạc một cách rõ ràng, mà ở pháp hội kinh Vô Lượng Thọ Ngài thuyết minh cho chúng sanh thấy nguyện lực đức Phật A Di Đà và nhân duyên mật thiết giữa chúng sanh cõi Ta bà với đức Phật này. Cũng chính trong pháp hội Vô Lượng Thọ, đức Thích Ca còn khẳng định rằng, chúng sanh cách Phật lâu xa về sau, ngoài pháp môn niệm Phật ra, không có pháp môn nào cứu giúp chúng sanh giải thoát luân hồi sanh tử có hiệu năng bằng pháp môn Tịnh độ. Và khi Phật pháp tận diệt hết trên cõi đời, chỉ còn lại độc nhất kinh Vô Lượng Thọ kéo dài thêm 100 năm nữa trước khi mạt pháp kết thúc. Người tu học Phật mà không đọc, không tin lời đức Phật nói ở kinh Vô Lượng Thọ, thì quả thật khó mà đạt đạo giác ngộ giải thoát."],["p","Nhận thấy lời huyền ký của đức Thích Ca về chân giá trị của pháp môn Tịnh độ và sự quý giá vô cùng của kinh Vô Lượng Thọ đối với người có thiện duyên chánh kiến chánh tâm, nhắm chánh đạo tiến bước, nên chúng tôi dịch bản kinh này để kết duyên Bồ đề cùng bạn lành bốn phương, để cùng nhau hướng về con đường sáng lành thênh thang trước mặt, con đường chắc chắn giải thoát. Đó chính là con đường Tịnh độ, con đường an toàn vững chắc."],["p","Trên con đường đó có đức Phật A Di Đà phóng quang soi sáng, có Thánh chúng hộ trì, có Bồ tát Quán Thế Âm, Thế Chí, Di Lặc dắt đường. Như thế là tự lực, tha lực đầy đủ đề huề đồng quy Cực Lạc. Trẻ thơ về quê có mẹ hiền cùng các anh chị đi bên cạnh thì còn lo gì lầm đường lạc lối?!"],["p","Ước mong bạn lành bốn phương sanh khởi tín tâm, tin lời Phật dạy, chánh niệm thực hành, thì nhất định cảnh giới Cực Lạc hiện tiền."],["v",["Mùa Vu Lan 1998","Thích Đức Niệm"]]]},{"t":"Nguyện Hương","b":[["p","(Quì gối đưa nhang lên nguyện hương.)"],["v",["Nguyện mây hương mầu này","Khắp cùng mười phương cõi","Cúng dường tất cả Phật","Tôn pháp, các Bồ Tát","Vô biên chúng Thanh Văn","Và cả thảy Thánh Hiền","Duyên khởi đài sáng chói","Trùm đến vô biên cõi,","Khắp xông các chúng sanh","Đều phát lòng bồ đề,","Hết một báo thân này","Sanh về cõi Cực Lạc."]],["p","Nam mô Hương Cúng Dường Bồ Tát. (1 lạy)"]]},{"t":"Tán Thán Phật","b":[["p","(Đứng lên đánh khánh tụng.)"],["p","Sắc Thân Như Lai đẹp, trong đời không ai bằng, không sánh, chẳng nghĩ bàn, nên nay con đảnh lễ."],["p","Sắc thân Phật vô tận, trí huệ Phật cũng thế, tất cả pháp thường trú, cho nên con về nương. Sức chí lớn nguyện lớn, khắp độ chúng quần sanh, khiến bỏ thân nóng khổ, sanh kia nước mát vui. Con nay sạch ba nghiệp, qui y và lễ tán, nguyện cùng các chúng sanh, đồng sanh nước Cực Lạc."]]},{"t":"Nhất Tâm Đảnh Lễ","b":[["p","(Đại chúng đồng tụng nhất tâm đảnh lễ.)"],["p","Nam Mô Thường Tịch Quang Tịnh Độ A Di Đà Như Lai Pháp Thân Mầu Thanh Tịnh Khắp Pháp Giới Chư Phật. (1 lạy)"],["p","Nam Mô Thật Báo Trang Nghiêm Độ A Di Đà Như Lai Thân Tướng Hải Vi Trần Khắp Pháp Giới Chư Phật. (1 lạy)"],["p","Nam Mô Phương Tiện Thánh Cư Độ A Di Đà Như Lai Thân Trang Nghiêm Giải Thoát Khắp Pháp Giới Chư Phật. (1 lạy)"],["p","Nam Mô Cõi An Lạc Phương Tây A Di Đà Như Lai Thân Căn Giới Đại Thừa Khắp Pháp Giới Chư Phật. (1 lạy)"],["p","Nam Mô Cõi An Lạc Phương Tây A Di Đà Như Lai Thân Hóa Đến Mười Phương Khắp Pháp Giới Chư Phật. (1 lạy)"],["p","Nam Mô Cõi An Lạc Phương Tây Giáo Hạnh Lý Ba Kinh Tột Nói Bày Y Chánh Khắp Pháp Giới Tôn Pháp. (1 lạy)"],["p","Nam Mô Cõi An Lạc Phương Tây Quán Thế Âm Bồ Tát Thân Tử Kim Muôn ức Khắp Pháp Giới Bồ Tát. (1 lạy)"],["p","Nam Mô Cõi An Lạc Phương Tây Đại Thế Chí Bồ Tát Thân Trí Sáng Vô Biên Khắp Pháp Giới Bồ Tát. (1 lạy)"],["p","Nam Mô Cõi An Lạc Phương Tây Thanh Tịnh Đại Hải Chúng Thân Hai Nghiêm Phước Trí Khắp Pháp Giới Thánh Chúng. (1 lạy)"]]},{"t":"Cử Tán","b":[["p","(Đại chúng đồng tụng theo tiếng mõ.)"],["v",["Lư hương vừa ngún chiên đàn,","Khói thơm ngào ngạt muôn ngàn cõi xa,","Lòng con kính ngưỡng thiết tha,","Ngưỡng mong chư Phật thương mà chứng"]],["p","minh Nam mô Hương Vân Cái Bồ Tát"],["p","Ma Ha Tát. (3 lần)"]]},{"t":"Bài Văn Phát Nguyện","b":[["v",["Nam mô Thập Phương Thường Trụ Tam","Bảo. (3 lần) Lạy đấng tam giới tôn","Quy mạng mười phương Phật","Nay con phát nguyện lớn","Trì tụng kinh Vô Lượng Thọ","Trên đền bốn ơn nặng","Dưới cứu khổ ba đường","Nếu có ai thấy nghe","Đều phát Bồ đề tâm","Khi mãn báo thân này","Sanh qua cõi Cực lạc.","Nam Mô Tây Phương Cực Lạc Thế Giới","Đại Từ Đại Bi A Di Đà Phật. (3 lần)"]]]},{"t":"Bài Kệ Khai Kinh","b":[["v",["Phật pháp rộng sâu rất nhiệm mầu","Trăm ngàn muôn kiếp khó tìm cầu","Nay con nghe thấy chuyên trì tụng,","Nguyện tỏ Như Lai nghĩa nhiệm mầu."]],["p","Nam Mô Đại Thừa Vô Lượng Thọ Hội"],["p","Thượng Phật Bồ Tát Ma Ha Tát. (3 lần)"]]},{"t":"Phật Nói Kinh Đại Thừa Vô Lượng Thọ Trang Nghiêm Thanh Tịnh Bình Đẳng Giác Phẩm Thứ Nhất Pháp Hội Thánh Chúng","b":[["p","Tôi nghe như vầy: một thuở nọ, đức Phật ở núi Kỳ Xà Quật nơi thành Vương Xá, cùng với đại thánh chúng Tỳ kheo một vạn hai ngàn vị đã chứng thần thông:"],["p","Tôn giả Kiều Trần Như, tôn giả Xá Lợi Phất, tôn giả Đại Mục Kiền Liên, tôn giả Ca Diếp, tôn giả A Nan v.v... là những bậc thượng thủ."],["p","Lại có các ngài Phổ Hiền Bồ Tát, Văn Thù Sư Lợi Bồ Tát, Di Lặc Bồ Tát và tất cả Bồ Tát trong hiền kiếp đến tập hội."]]},{"t":"Phẩm Thứ Hai Đức Tuân Phổ Hiền","b":[["p","Lại có mười sáu vị Bồ Tát tại gia:"],["p","Hiền Hộ Bồ Tát, Thiện Tư Duy Bồ Tát, Huệ Biện Tài Bồ Tát, Quán Vô Trú Bồ Tát, Thần Thông Hoa Bồ Tát, Quang Anh Bồ Tát, Bảo Tràng Bồ Tát, Trí Thượng Bồ Tát, Tịch Căn Bồ Tát, Tín Huệ Bồ Tát, Nguyện Huệ Bồ Tát, Hương Tượng Bồ Tát, Bảo Anh Bồ Tát, Trung Trú Bồ Tát, Chế Hạnh Bồ Tát, Giải Thoát Bồ Tát, là những bậc thượng thủ. Các vị Bồ Tát này đều tuân theo hạnh nguyện của Phổ Hiền Đại sĩ, thật hành vô lượng hạnh nguyện quyền hành phương tiện đi khắp mười phương làm các công đức, vào pháp tạng của chư Phật, rốt ráo giải thoát, nguyện chúng sanh ở vô lượng thế giới đồng chứng Phật quả. Rời cung trời Đâu Suất, giáng sinh vào cung vua, bỏ ngôi vị mà xuất gia, khổ hạnh học đạo."],["p","Thị hiện thuận theo thế gian pháp, đem sức định huệ hàng phục ma oán, đắc pháp vi diệu thành bậc tối chánh giác, người trời qui ngưỡng. Chuyển bánh xe pháp, đem pháp âm giác ngộ thế gian, phá thành phiền não, lấp ao tham dục, gột sạch cấu uế, hiển bày đức thanh tịnh, điều phục chúng sanh, tuyên thuyết diệu lý, tích công lũy đức, gây tạo phước điền."],["p","Đem pháp dược cứu liệu các khổ ba cõi."],["p","Làm phép quán đảnh thọ ký Bồ đề. Giáo hóa Bồ Tát nên làm A xà lê biểu thị vô biên công hạnh, thành thục vô biên thiện căn cho hàng Bồ Tát. Vô lượng chư Phật đồng đến hộ niệm. Trong tất cả cõi Phật đều có thể thị hiện như vậy. Như nhà ảo thuật biến ra các hình tướng, nhưng các hình ấy không có thật tướng. Bậc Bồ Tát này cũng lại như vậy, đã thông đạt tánh tướng của chúng sanh, cúng dường chư Phật. Dắt dẫn quần sanh, hóa hiện các thân, mau như ánh chớp. Phá tan lưới chấp, thoát dây ràng buộc, qua khỏi quả vị Thanh văn Bích chi, chứng nhập ba pháp: Không, vô tướng, vô nguyện. Khéo lập phương tiện hiển thị ba thừa. Đối với hàng trung hạ căn thị hiện có diệt độ."],["p","Chứng đắc vô sanh vô diệt, vào sâu thiền định, được vô lượng trăm ngàn pháp tổng trì. Ngộ nhập Hoa Nghiêm tam muội, chứng trăm ngàn tổng trì tam muội, vẫn trụ sâu trong thiền định, thấy rõ vô lượng đức Phật. Khoảnh khắc đi khắp cõi Phật, được biện tài của Phật. Vào hạnh nguyện Phổ Hiền."],["p","Thông đạt tiếng nói các chúng sanh, khai thị thật tướng vũ trụ. Vượt khỏi các pháp thế gian. Tâm thường nguyện độ thoát chúng sanh. Đối với vạn vật tùy ý tự tại. Với lục đạo phàm phu làm bạn không thỉnh. Vâng giữ pháp tạng nhiệm mầu Như Lai, hộ trì giống Phật khiến không dứt. Phát rộng lòng thương xót hữu tình, nói lời từ ái, trao pháp nhãn, đóng đường ác, mở cửa lành. Đối với chúng sanh biểu hiện cởi mở, cứu giúp phò trợ, mong độ chúng sanh đến bờ giác ngộ. Quyết được vô lượng công đức. trí huệ sáng suốt không thể nghĩ bàn."],["p","Vô lượng vô biên đại Bồ Tát như vậy đồng đến pháp hội. Lại có năm trăm vị Tỳ kheo ni, bảy ngàn vị Ưu bà tắc, năm trăm vị Ưu bà di, và chư thiên cõi Dục, cõi sắc, cõi Phạm chúng đồng đến dự đại hội."]]},{"t":"Phẩm Thứ Ba Đại Giáo Duyên Khởi","b":[["p","Bấy giờ đức Thế Tôn hiện trăm ngàn sắc tướng oai quang sáng chói, như gương sáng sạch chiếu rõ vạn pháp."],["p","Tôn giả A Nan liền tự suy nghĩ, ngày nay đức Thế Tôn hiện sắc tướng nghiêm tịnh rạng rỡ nguy nguy, cõi nước trang nghiêm, từ trước đến nay ta chưa từng thấy, thật là hi hữu, liền từ chỗ ngồi đứng dậy trịch áo vai hữu quỳ gối chấp tay bạch đức Phật rằng: “Bạch đức Thế Tôn!"],["p","Hôm nay Thế Tôn vào Đại Tịch Định, an trụ trong pháp đặc biệt, an trụ trong pháp hạnh tối thắng của chư Phật. Quá hiện vị lai, Phật Phật nhớ nhau. Thế Tôn vì nhớ chư Phật quá khứ, chư Phật vị lai hay nhớ chư Phật hiện tại phương khác?"],["p","Vì sao lại có oai thần hiển diệu thù đặc như vậy, cúi xin đức Thế Tôn chỉ dạy”."],["p","Bấy giờ đức Phật bảo tôn giả A Nan: “Lành thay! Lành thay! Ông vì thương xót lợi lạc các chúng sanh mới hỏi điều vi diệu như vậy. Lời thưa hỏi của ông hôm nay công đức thù thắng hơn trăm ngàn vạn lần nhiều kiếp bố thí cúng dường các bậc A la hán, Bích chi Phật cùng chư Thiên, nhân loại và các loài bò bay xuẩn động trong một thiên hạ. Vì sao vậy? Chư Thiên, nhân loại và tất cả hàm linh đời sau đều nhơn lời hỏi của ông hôm nay mà được độ thoát."],["p","Này A Nan! Như Lai vì lòng đại bi vô tận thương xót ba cõi nên xuất hiện ở đời, tuyên dương giáo pháp là muốn cứu bạt quần manh, đem lợi ích chân thật, khó gặp khó thấy, như hoa ưu đàm hiếm khi xuất hiện, lời hỏi hôm nay của ông lợi ích rất lớn."],["p","A Nan nên biết: Trí chánh giác của Như Lai rất khó suy lường, không gì chướng ngại được. Có thể trong một niệm an trụ vô lượng kiếp, thân và các căn không có sanh diệt. Vì sao vậy?"],["p","Định huệ của Như Lai thông đạt vô cùng, tối thắng tự tại với tất cả pháp. A Nan hãy lắng nghe, khéo nghĩ nhớ đó, ta sẽ vì ông phân biệt giải rõ."]]},{"t":"Phẩm Thứ Tư Pháp Tạng Nhân Địa","b":[["p","Này A Nan: ở vô lượng vô số kiếp về đời quá khứ lâu xa có đức Phật xuất thế hiệu là Thế Gian Tự Tại Vương Như Lai, Ứng cúng, Đẳng chánh giác, Minh hạnh túc, Thiện thệ, Thế gian giải, Vô thượng sĩ, Điều ngự Trượng phu, Thiên Nhân Sư, Phật, Thế Tôn. Đức Phật đó trụ thế hóa độ bốn mươi hai kiếp. Vì hàng chư Thiên và nhân loại mà thuyết giảng kinh pháp”."],["p","Bấy giờ có vị vua tên là Thế Nhiêu nghe Phật thuyết giảng đạo lý, tâm sanh hoan hỷ lãnh ngộ, liền phát tâm Vô thượng chơn chánh, bèn trao ngôi vua theo Phật xuất gia làm sa môn hiệu là Pháp Tạng. Tu hạnh Bồ Tát, đức hạnh cao siêu trí huệ dõng mãnh, thâm tín lý giải đệ nhất. Lại có hạnh nguyện thù thắng, định huệ tăng thượng kiên cố bất động, tu hành tinh tấn, đến trước đức Phật đảnh lễ quỳ gối chắp tay tán thán phát đại thệ nguyện, nói kệ rằng:"],["v",["Thân Như Lai vi diệu đoan nghiêm","Thế gian không ai sánh kịp được","Sáng ngời vô lượng khắp mười"]],["v",["phương Nhựt nguyệt hỏa châu lu mờ cả.","Thế Tôn diễn thuyết một âm thanh","Tùy loại hữu tình thảy thông hiểu","Lại hay hiện sắc thân đẹp đẽ","Tùy loại chúng sanh đều thấy rõ.","Nguyện con thành Phật có tiếng tốt","Đưa Pháp âm đến vô biên cõi,","Tuyên dương pháp: Giới, định, tinh","tấn."]],["p","Thông đạt rộng sâu pháp nhiệm mầu Trí huệ rộng lớn như biển cả"],["v",["Nội tâm thanh tịnh dứt trần lao","Ra hẳn vô biên đường ác thú","Mau đến Bồ đề bờ cứu cánh.","Vô minh tham sân đều dứt sạch","Tuyệt hẳn vọng hoặc, đắc tam muội","Như vô lượng Phật đời quá khứ,","Làm đại Đạo sư khắp quần sanh,","Hay cứu tất cả sự khổ não","Sanh già bịnh chết của chúng sanh.","Thường tu bố thí, giới, nhẫn nhục","Tinh tấn, định, huệ sáu Ba la.","Hữu tình chưa độ khiến được độ,","Kẻ đã độ rồi khiến thành Phật.","Giả sử cúng dường hằng sa Thánh,","Không bằng kiên dõng cầu Chánh"]],["v",["giác.","Nguyện an trụ vào Tam ma địa","Hằng phóng hào quang chiếu khắp"]],["v",["nơi Chạm đến được vào nơi thanh tịnh,","Thù thắng trang nghiêm không ai","bằng, Chúng sanh luân hồi trong các cõi,","Mau về cõi con hưởng an lạc.","Thường vận từ tâm cứu hữu tình,","Độ tận vô biên chúng sanh khổ.","Con nguyền quyết định kiên cố tu,","Xin Phật thánh trí chứng biết cho,","Dù cho thân nát trong các khổ,","Nguyện tâm như vậy thề không thối."]]]},{"t":"Phẩm Thứ Năm Chí Tâm Tinh Tấn","b":[["p","Pháp Tạng Tỳ kheo nói bài kệ này rồi liền bạch đức Phật rằng: “Bạch đức Thế Tôn! Con nay tu hạnh Bồ Tát, đã phát tâm Vô thượng Chánh giác, giữ nguyện làm Phật, tất được như Phật. Nguyện đức Phật vì con rộng giảng kinh pháp, con xin phụng trì, như pháp tu hành, dứt sạch gốc khổ sanh tử, mau chứng Vô thượng Chánh đẳng Chánh giác."],["p","Nguyện khi con thành Phật, trí huệ sáng suốt, hào quang sáng chói, tiếng tăm quốc độ lan khắp mười phương; trời người cho đến súc sanh, sanh vào cõi nước con đều thành Bồ Tát. Nguyện con lập đây tất cả đều hơn các cõi Phật khác, có được chăng?”"],["p","Đức Phật Thế Gian Tự Tại Vương liền nói với Pháp Tạng rằng: “Thí như có người lường nước biển trải qua nhiều kiếp còn có thể đến đáy. Ngươi đã hết lòng cầu đạo tinh tấn không dứt, quyết sẽ được kết quả! Vậy thì nguyện gì mà chẳng thành?"],["p","Ngươi tự suy nghĩ tu phương tiện nào để thành tựu được cõi Phật trang nghiêm. Việc tu hành như thế ngươi nên tự biết, với việc thanh tịnh cõi Phật, ngươi nên tự nhiếp. Pháp Tạng bạch rằng: “Bạch đức Thế Tôn! Điều ấy quá sâu rộng, không phải cảnh giới của con hiểu được, cúi xin đức Như Lai Ứng Chánh Biến Tri rộng nói vô lượng vi diệu cõi nước của chư Phật, khi con được nghe các pháp như vậy rồi, suy nghĩ tu tập, thệ nguyện con mới được viên mãn”."],["p","Đức Phật Thế Gian Tự Tại Vương biết rõ chí nguyện sâu rộng của Pháp Tạng, liền nói công đức nghiêm tịnh rộng lớn viên mãn cõi nước của hai trăm mười ức đức Phật đúng theo tâm nguyện ông mong muốn, trải qua ngàn ức năm. Bấy giờ Pháp Tạng Tỳ kheo nghe Phật nói rồi, đã được thấy rõ, liền phát nguyện vô thượng thù thắng. Nơi các cõi xấu, đẹp, thiện, ác, của trời người suy lường rốt ráo. Chuyên tâm chọn lựa, kết thành đại nguyện, tinh cần cầu tiến, kính cẩn duy trì tu tập công đức đầy đủ năm kiếp. Ở nơi hai mươi mốt vô số cõi Phật công đức trang nghiêm, rõ ràng thông suốt thành một nước Phật. Khi đã tu tập rồi, lại đến chỗ của Như Lai Thế Tự Tại Vương, cúi đầu lạy sát chân, nhiễu Phật ba vòng rồi, đứng yên chắp tay bạch đức Phật rằng: “Bạch đức Thế Tôn! Con đã thành tựu viên mãn hạnh nguyện trang nghiêm thanh tịnh nước Phật”."],["p","Đức Phật nói: “Lành thay! Lành thay!"],["p","Nay chính phải lúc ông nên nói rõ để mọi người vui mừng, cũng để đại chúng nghe rồi được nhiều lợi lớn, có thể ở cõi Phật đó tu tập nhiếp thọ trọn đủ vô lượng đại nguyện”."]]},{"t":"Phẩm Thứ Sáu Phát Đại Thệ Nguyện","b":[["p","Pháp Tạng bạch rằng: “Bạch đức Thế Tôn! Cúi xin đức Thế Tôn thương xót nghe cho:"],["p","● Con nếu chứng được Vô thượng Bồ"],["p","Đề, thành Đẳng chánh giác rồi, cõi nước của Phật ở có đầy đủ vô lượng công đức trang nghiêm không thể nghĩ bàn, không có địa ngục, ngạ quỷ, súc sanh các loại. Nếu có chúng sanh trong ba đường ác cho đến từ địa ngục sanh về cõi con, thọ giáo pháp của con, tất thành A Nậu Đa La Tam Miệu Tam Bồ Đề, không đọa lại ba đường ác nữa. Được như vậy con mới làm Phật. Nếu không được như nguyện, thề không thành Vô thượng Chánh giác."],["v",["[1. Nguyện trong nước không có ác đạo.","2. Nguyện không đọa ba đường ác.]","● Khi con thành Phật, các chúng sanh"]],["p","ở mười phương thế giới sanh về cõi con, thân tướng sắc vàng ròng, đủ ba mươi hai tướng tốt, đủ tướng đại trượng phu, đoan nghiêm chánh trực, tất cả đồng một dung nhan, nếu có tốt xấu, hình thể sai biệt, thề không thành Chánh giác."],["p","[3. Nguyện thân có sắc vàng ròng. 4. Nguyện có ba mươi hai tướng tốt. 5. Nguyện cho thân không sai biệt.]"],["p","● Khi con thành Phật, các chúng sanh"],["p","sanh về cõi con, biết rõ vô lượng kiếp trước. Thấy rõ những việc thiện ác đã làm. Nghe rõ sự việc khắp mười phương cả ba đời khứ lai hiện tại."],["p","Nếu không được như nguyện, thề không thành Chánh giác."],["p","[6. Nguyện có túc mạng thông. 7. Nguyện có thiên nhãn thông. 8. Nguyện có thiên nhĩ thông.]"],["p","● Khi con thành Phật, nếu có chúng"],["p","sanh sanh về cõi con đều được tha tâm trí thông, biết được tâm niệm của chúng sanh xa cách trăm ngàn vạn ức cõi Phật, nếu không như vậy thề không thành Chánh giác."],["p","[9. Nguyện có tha tâm thông.]"],["p","● Khi con thành Phật, nếu có chúng"],["p","sanh sanh về cõi con, được thần thông tự tại Ba la mật đa. Trong khoảnh khắc nếu không đi khắp trăm ngàn vạn ức cõi Phật để cúng dường, thề không thành Chánh giác."],["p","[10. Nguyện được thần túc thông. 11. Nguyện giáp khắp cúng dường chư Phật.]"],["p","● Khi con thành Phật, nếu có chúng"],["p","sanh sanh về cõi con, xa lìa tâm phân biệt, các căn tịch tịnh, nếu chẳng an trụ trong định tụ đến đại Niết bàn, thề không thành Chánh giác."],["p","[12. Nguyện quyết định thành bậc Chánh giác.]"],["p","● Khi con thành Phật, có quang minh"],["p","vô lượng chiếu khắp mười phương chư Phật, gấp ngàn vạn ức lần ánh sáng của nhựt nguyệt. Nếu có chúng sanh nào thấy hay chạm được ánh sáng của con thì được an lạc, khởi từ tâm làm điều lành, sau sanh về nước con. Nếu không được như vậy, thề không thành Chánh giác."],["p","[13. Nguyện ánh sáng vô lượng. 14. Nguyện chạm Quang minh được an lạc.]"],["p","● Khi con thành Phật sống lâu vô"],["p","lượng. Vô số Thanh văn và trời người trong nước cũng có thọ mạng vô lượng. Giả như chúng sanh ở ba ngàn thế giới thành bậc Duyên giác trải qua trăm ngàn kiếp để tính đếm, nếu biết được số lượng ấy, thề không thành Chánh giác."],["v",["[15. Nguyện thọ mạng vô lượng.","16. Nguyện Thanh văn vô số.]","● Khi con thành Phật, vô số chư Phật"]],["p","trong vô lượng cõi ở mười phương thế giới, nếu không khen ngợi tên con, nói công đức quốc độ của con, thề không thành Chánh giác."],["p","[17. Nguyện được chư Phật xưng tán.]"],["p","● Khi con thành Phật, chúng sanh"],["p","trong mười phương nghe danh hiệu con, hết lòng tin tưởng, nếu có điều lành nào, tâm tâm hồi hướng nguyện sanh về cõi nước con, cho đến mười niệm, nếu không được vãng sanh, thề không thành Chánh giác. Ngoại trừ những kẻ phạm tội ngũ nghịch, phỉ báng chánh pháp."],["p","[18. Nguyện mười niệm tất vãng sanh.]"],["p","● Khi con thành Phật, chúng sanh"],["p","khắp mười phương nghe danh hiệu con, phát tâm Bồ đề, tu các công hạnh, hành sáu Ba la mật, kiên cố không lùi, lại đem các căn lành hồi hướng nguyện sanh về cõi nước con, một lòng nghĩ đến con ngày đêm không dứt, đến khi mạng chung, con cùng Thánh chúng Bồ Tát liền đến tiếp đón, khoảnh khắc sanh về cõi con được Bất thối chuyển. Nếu không được như nguyện, thề không thành Chánh giác."],["p","[19. Nguyện nghe danh phát tâm. 20. Nguyện lâm chung tiếp dẫn.]"],["p","● Khi con thành Phật, chúng sanh"],["p","trong mười phương nghe danh hiệu con, nhớ nghĩ nước con, phát tâm Bồ đề kiên cố không thối lui, trồng các căn lành, hết lòng hồi hướng sanh về Cực Lạc, đều được toại ý; nếu có ác nghiệp đời trước, nghe danh hiệu con hết lòng sám hối, làm các điều lành, lại trì kinh giữ giới nguyện sanh về nước con, mạng chung không lạc vào ba đường ác, liền sanh về nước con. Nếu không được như vậy, thề không thành Chánh giác."],["p","[21. Nguyện sám hối được vãng sanh.]"],["p","● Khi con thành Phật, nước con không"],["p","có phụ nữ. Nếu có nữ nhơn nào nghe danh hiệu con, thanh tịnh tin tưởng, phát tâm Bồ đề, chán ghét nữ thân, mạng chung liền hóa thân nam tử sanh về nước con. Các loại chúng sanh ở thế giới mười phương, sanh về nước con đều hóa sanh trong hoa sen thất bảo. Nếu không được như vậy, thề không thành Chánh giác."],["p","[22. Nguyện trong nước không có người nữ. 23. Nguyện nhàm chán thân nữ, chuyển thân nam."],["p","24. Nguyện Liên hoa hóa sanh.]"],["p","● Khi con thành Phật, chúng sanh"],["p","khắp mười phương nghe danh hiệu con vui mừng tin tưởng, lễ bái qui mạng, đem tâm thanh tịnh tu hạnh Bồ tát, chư Thiên và người đời hết lòng tôn kính. Nếu nghe danh hiệu con, sau khi mạng chung được sanh vào nhà tôn quý, các căn đầy đủ."],["p","Thường tu thù thắng phạm hạnh."],["p","Nếu không được như vậy, thề không thành Chánh giác."],["p","[25. Nguyện Thiên Nhân lễ kính. 26. Nguyện nghe danh hiệu được phước."],["p","27. Nguyện tu thù thắng hạnh.]"],["p","● Khi con thành Phật, nước con không"],["p","có tên ba đường ác. Chúng sanh sanh vào nước con đều nhất tâm trụ vào chánh định. Không còn nhiệt não, tâm được mát mẻ, hưởng thọ an lạc, như Tỳ kheo lậu tận. Nếu còn khởi tưởng niệm tham đắm thân sau, thề không thành Chánh giác."],["p","[28. Nguyện nước không có tên “Bất thiện”."],["p","29. Nguyện trụ Chánh định tụ. 30. Nguyện vui như Tỳ kheo dứt sạch các lậu."],["p","31. Nguyện không tham chấp thân.]"],["p","● Khi con thành Phật, chúng sanh"],["p","sanh vào nước con, được vô lượng căn lành, thân thể vững chắc như kim cang bất hoại, thân mình đều có hào quang chiếu sáng. Thành tựu hết thảy trí huệ, biện tài không cùng tận. Rộng nói các pháp bí yếu, giảng kinh thuyết pháp, tiếng như chuông vang. Nếu không được như vậy, thề không thành Chánh giác."],["p","[32. Nguyện được Na la diên thân. 33. Nguyện Quang minh trí huệ biện tài."],["p","34. Nguyện khéo nói pháp yếu.]"],["p","● Khi con thành Phật, chúng sanh"],["p","sanh vào nước con quyết chắc đến bậc Nhất Sanh Bổ Xứ. Trừ khi phát nguyện rộng lớn trở lại độ sanh, giáo hóa hữu tình, khuyến phát tín tâm, tu hạnh Bồ tát, hành nguyện Phổ Hiền, tuy sanh vào thế giới khác hằng lìa ác thú, hoặc thích thuyết pháp, nghe pháp, hay hiện thần túc, tùy ý tu tập thảy đều viên mãn. Nếu không được như vậy, thề không thành Chánh giác."],["v",["[35. Nguyện nhất sanh bổ xứ.","36. Nguyện giáo hóa tùy ý.]","● Khi con thành Phật, chúng sanh"]],["p","sanh vào nước con, nếu muốn ăn uống, y phục hay các đồ cần dùng tùy ý liền đến. Nếu khởi niệm cúng dường mười phương chư Phật, liền được mãn nguyện. Nếu không được như vậy, thề không thành Chánh giác."],["p","[37. Nguyện y thực tự đến. 38. Nguyện ứng niệm thọ cúng.]"],["p","● Khi con thành Phật, vạn vật trong"],["p","cõi nước con đều trang nghiêm thanh tịnh sáng chói, hình sắc thù thắng vi diệu không thể tả xiết, dù có thiên nhãn cũng không thể diễn tả hết vẻ đẹp về hình sắc, hình tướng lộng lẫy và số lượng chúng sanh ở đó v.v... Nếu không được như vậy, thề không thành Chánh giác."],["p","[39. Nguyện trang nghiêm vô tận.]"],["p","● Khi con thành Phật, vô lượng cây"],["p","cảnh trong cõi nước con cao trăm ngàn do tuần. Cây làm đạo tràng cao bốn trăm vạn dặm. Các bậc Bồ Tát trung phẩm cũng có thể biết rõ. Nếu muốn thấy các cõi thanh tịnh trang nghiêm của chư Phật, tuy ở nơi cây báu cũng được thấy rõ vạn tượng như xem trong gương. Nếu không được như vậy, thề không thành Chánh giác."],["v",["[40. Nguyện có vô lượng cây sắc báu.","41. Nguyện cây hiện cõi Phật.]","● Khi con thành Phật, cõi nước rộng"]],["p","rãi nghiêm tịnh, sáng chói như gương, chiếu khắp vô lượng vô số bất khả tư nghì thế giới chư Phật khắp mười phương, chúng sanh thấy rồi sanh tâm hi hữu. Nếu không được như vậy, thề không thành Chánh giác."],["p","[42. Nguyện chiếu suốt mười phương.]"],["p","● Khi con thành Phật, cùng tột dưới"],["p","đất, trên đến hư không, tất cả vạn vật cung điện, lầu các, ao nước, hoa cây v.v... trong nước đều do vô lượng bảo hương hiệp thành, hương thơm xông khắp mười phương thế giới, chúng sanh ngửi được đều tu Phật hạnh. Nếu không được như vậy, thề không thành Chánh giác."],["p","[43. Nguyện hương báu xông khắp.]"],["p","● Khi con thành Phật, các bậc Bồ Tát"],["p","trong mười phương cõi Phật, nghe danh con rồi đều được thanh tịnh giải thoát, Phổ đẳng Tam muội, các môn Tổng trì vào Tam ma địa cho đến thành Phật. Tuy ở trong định thường cúng dường vô lượng vô biên chư Phật vẫn không mất định ý. Nếu không được như vậy, thề không thành Chánh giác."],["p","[44. Nguyện phổ đẳng tam muội. 45. Nguyện trong định cúng Phật.]"],["p","● Khi con thành Phật, các bậc Bồ Tát ở"],["p","thế giới khác nghe danh con rồi chứng Ly sanh pháp, được các môn Đà la ni. Thanh tịnh hoan hỷ, an trụ trong thể tướng bình đẳng, tu Bồ Tát hạnh, đầy đủ trí đức mà không chứng được ba nhẫn, nơi Phật pháp mà không chứng được bậc Bất thối chuyển, thề không thành Chánh giác”."],["p","[46. Nguyện được môn Tổng trì. 47. Nguyện nghe danh đặng pháp nhẫn. 48. Nguyện hiện chứng quả bất thối chuyển.]"]]},{"t":"Phẩm Thứ Bảy Quyết Thành Chánh Giác","b":[["p","Này A Nan: Bấy giờ Tỳ kheo Pháp Tạng phát nguyện rồi, liền đọc bài tụng:"],["v",["Con lập nguyện hơn đời,","Tất đến đạo Vô Thượng,","Nguyện này nếu không toại,","Thề không thành Chánh giác.","Lại làm đại thí chủ","Cứu khắp kẻ cùng khổ,","Khiến các quần sanh kia,","Đêm dài không ưu não,","Phát sanh các căn lành,","Thành tựu quả Bồ đề.","Con nếu thành Chánh giác,","Lấy tên Vô Lượng Thọ.","Chúng sanh nghe danh này","Sanh về cõi nước con,","Thân kim sắc như Phật,","Tướng tốt thảy viên mãn,","Cũng đem tâm đại bi,","Lợi ích các quần sanh,","Ly dục sâu thiền định","Tịnh huệ tu phạm hạnh.","Nguyện đem trí huệ sáng,","Chiếu khắp mười phương cõi,","Tiêu trừ ba độc hại","Cứu khỏi các ách nạn,","Dứt sạch khổ tam đồ,","Diệt hết phiền não ám,","Khai sáng mắt trí huệ,","Chứng được thân quang minh","Đóng hết ba đường ác,","Mở rộng các cửa lành.","Vì chúng khai tạng pháp,","Rộng thí báu công đức,","Trí vô ngại như Phật,","Làm các hạnh từ mẫn.","Đạo Sư cả trời người,","Anh hùng khắp ba cõi,","Thuyết pháp sư tử hống,","Rộng độ các hữu tình","Viên mãn lời phát nguyện,","Tất cả đều thành Phật.","Nguyện này nếu thành tựu,","Đại thiên thảy chấn động.","Các thiên thần trên không,","Mưa xuống trân diệu hoa."]],["p","Này A Nan! Tỳ kheo Pháp Tạng nói bài tụng này rồi, mặt đất chấn động sáu cách. Hoa trời rưới khắp, âm nhạc tự trỗi, không trung vang lời khen: Quyết chắc thành Vô thượng Chánh giác."]]},{"t":"Phẩm Thứ Tám Tích Công Lũy Đức","b":[["p","Này A Nan! Pháp Tạng Tỳ kheo ở trước Như Lai Thế Tự Tại Vương và giữa đại chúng trời người phát hoằng thệ nguyện này rồi, an trụ trong huệ chân thật, dõng mãnh tinh tấn một hướng chuyên tâm trang nghiêm cõi nước, xây dựng Phật quốc rộng lớn, siêu việt thắng diệu, kiến lập vĩnh viễn, tuyệt không hư hoại, không biến đổi. Trong vô lượng kiếp vun trồng đức hạnh, không khởi tưởng dục ba độc, chẳng đắm sáu trần, chỉ chuyên nhớ nghĩ chư Phật thuở quá khứ đã tu căn lành, hành hạnh tịch tịnh, xa lìa luống dối, y chơn đế môn, làm các công đức, không nề các khổ, ít muốn biết đủ, chuyên cầu pháp thanh tịnh, đem ân huệ lợi ích quần sanh, chí nguyện không mỏi, thành tựu các nhẫn. Đối với hữu tình nói lời từ ái vui vẻ hòa dịu khuyến dụ khích lệ. Cung kính Tam bảo, phụng sự sư trưởng. Không giả dối nịnh hót, nghiêm trang đứng đắn, khuôn phép nhứt mực."],["p","Quán pháp như huyễn, tam muội thường tịch. Giữ gìn khẩu nghiệp, không nói lỗi người, giữ gìn thân nghiệp, không mất oai nghi, giữ gìn ý nghiệp, thanh tịnh không nhiễm. Nếu có quốc thành xóm làng quyến thuộc trân bảo, không sanh tham trước, hằng hành bố thí, trì giới, nhẫn nhục, tinh tấn, thiền định, trí huệ sáu Ba la mật. Giáo hóa chúng sanh an trụ đạo Vô thượng Chánh giác. Do thành thục các căn lành như vậy, nên sanh đến chỗ nào tự nhiên cảm ứng có vô lượng kho báu, hoặc làm trưởng giả cư sĩ, hào hiệp tôn quý, hoặc làm Sát lợi Quốc vương, Chuyển luân Thánh vương, hoặc làm vua trời cõi Lục dục cho đến Phạm vương, cung kính cúng dường chư Phật chưa từng gián đoạn. Những công đức như vậy chẳng thể kể hết."],["p","Miệng thường tỏa hương thơm như hương chiên đàn, hương thơm hoa sen, hương thơm ấy xông khắp vô lượng thế giới. Phàm sanh ra chỗ nào sắc tướng cũng đoan nghiêm, đủ ba mươi hai tướng tốt, tám mươi nét đẹp. Tay thường xuất sanh châu báu vô tận, tất cả đồ cần dùng đẹp đẽ tối thượng để lợi lạc hữu tình. Do nhân duyên ấy, khiến vô lượng chúng sanh phát tâm A Nậu Đa La Tam Miệu Tam Bồ Đề."]]},{"t":"Phẩm Thứ Chín Thành Tựu Viên Mãn","b":[["p","Này A Nan! Pháp Tạng Tỳ kheo tu hạnh Bồ Tát, tích công lũy đức vô lượng vô biên trong tất cả pháp mà được tự tại, không thể dùng lời diễn tả hết chỗ phát thệ, thành tựu viên mãn như thật an trụ cụ túc trang nghiêm, oai đức rộng lớn thanh tịnh cõi Phật được."],["p","Tôn giả A Nan nghe đức Phật nói lời ấy rồi, cung kính thưa rằng: Bạch đức Thế Tôn! Pháp Tạng Bồ Tát chứng Bồ đề là đã thành Phật và nhập diệt rồi hay chưa thành Phật, hay đã thành Phật hiện ở thế giới khác?"],["p","Đức Thế Tôn nói: “Đức Phật Như Lai kia, đến không chỗ đến, đi không chỗ đi, không sanh không diệt, không có quá hiện vị lai, chỉ có một nguyện độ sanh."],["p","Hiện ở phương Tây cách Diêm phù đề này mười vạn ức cõi Phật, thế giới đó gọi là Cực Lạc, Pháp Tạng thành Phật hiệu là A Di Đà. Thành Phật đến nay đã mười kiếp, hiện đang thuyết pháp, có vô lượng vô số chúng Bồ Tát, Thanh văn cung kính vây quanh”."]]},{"t":"Phẩm Thứ Mười Đều Nguyện Làm Phật","b":[["p","Lúc đức Phật nói A Di Đà Phật khi làm Bồ Tát viên mãn hạnh nguyện rồi, A Xà Vương tử cùng với năm trăm trưởng giả biết được đều rất vui mừng, mỗi mỗi cầm một bó hoa bằng vàng đến trước Phật đảnh lễ và dâng hoa xong ngồi về một phía. Họ đồng tâm nguyện rằng, khi chúng tôi thành Phật đều như đức Phật A Di Đà”."],["p","Đức Phật biết tâm nguyện của họ, bảo các Tỳ kheo rằng: “Các vương tử này sau sẽ thành Phật. Đời trước khi còn tu hạnh Bồ Tát, trải qua vô số kiếp đã cúng dường bốn trăm ức đức Phật. Thời Phật Ca Diếp họ là đệ tử ta, nay lại đến cúng dường ta”. Các Tỳ kheo nghe đức Phật nói đều rất vui mừng."]]},{"t":"Phẩm Mười Một Cõi Nước Nghiêm Tịnh","b":[["p","Này A Nan! Cõi Cực Lạc kia có vô lượng công đức đầy đủ trang nghiêm, tuyệt không có danh từ khổ nạn, ác thú ma não, cũng không có bốn mùa nóng lạnh sáng tối, không có sông biển lớn nhỏ, gò nổng hầm hố, gai gốc đá sỏi, núi Thiết vi, núi Tu di, đất đá núi non, chỉ là tự nhiên bằng bảy báu. Vàng ròng làm đất rộng rãi bằng phẳng không có hạn lượng, kỳ diệu tú lệ, thanh tịnh trang nghiêm, thù thắng hơn tất cả thế giới khắp mười phương."],["p","Tôn giả A Nan nghe rồi thưa Phật: “Bạch đức Thế Tôn! Nếu cõi đó không có núi Tu di thì Tứ Thiên Vương và Đao Lợi Thiên nương tựa vào đâu?”"],["p","Này A Nan! Trời Dạ Ma, Trời Đâu Suất cho đến chư Thiên cõi Sắc và Vô sắc nương vào đâu?"],["p","Tôn giả A Nan thưa: “Bạch đức Thế Tôn! Do nghiệp lực tạo nên không thể nghĩ bàn được”."],["p","Đức Phật hỏi A Nan: “Bất tư nghì nghiệp ông có thể biết chăng?”"],["p","Quả báo thân ông bất khả tư nghì, nghiệp báo chúng sanh cũng bất khả tư nghì, căn lành của chúng sanh bất khả tư nghì, Thánh lực chư Phật, thế giới chư Phật cũng bất khả tư nghì, đất nước chúng sanh, công đức thiện lực, trú hành nghiệp địa và thần lực chư Phật cũng đều như vậy cả”."],["p","Tôn giả A Nan thưa: “Bạch đức Thế Tôn! Nghiệp nhân và quả báo không thể nghĩ bàn được. Đối với pháp này thật con không hoài nghi, nhưng vì muốn phá trừ sự nghi ngờ của chúng sanh đời sau nên thưa hỏi lời này”."]]},{"t":"Phẩm Mười Hai Ánh Sáng Chiếu Khắp","b":[["p","Này A Nan! Oai thần và quang minh của Phật A Di Đà tối tôn đệ nhất, quang minh của chư Phật khác chẳng sánh kịp."],["p","Quang minh ấy chiếu khắp hằng sa cõi Phật ở Phương Đông, Tây, Nam, Bắc, trên dưới và bốn phương phụ cũng lại như vậy."],["p","Hào quang trên đảnh chiếu xa một hai ba bốn do tuần, hoặc trăm ngàn vạn ức do tuần. Hào quang các đức Phật khác hoặc chiếu đến một hai cõi Phật, hoặc trăm ngàn cõi Phật, chỉ có hào quang đức Phật A Di Đà chiếu khắp vô lượng vô số vô biên cõi Phật. Hào quang chư Phật chiếu ra có xa có gần vì bổn nguyện công đức đời trước cầu đạo có lớn nhỏ không đồng, nên khi thành Phật tự có hạn lượng."],["p","Quang minh đức Phật A Di Đà sáng chói gấp bội trăm ngàn vạn lần ánh sáng nhựt nguyệt, tôn quý trong các ánh sáng, nên Phật Vô Lượng Thọ cũng hiệu là Phật Vô Lượng Quang, Phật Vô Biên Quang, Phật Vô Ngại Quang, Phật Vô Đẳng Quang, Phật Trí Huệ Quang, Phật Thường Chiếu Quang, Phật Thanh Tịnh Quang, Phật Hoan Hỷ Quang, Phật Giải Thoát Quang, Phật An Ổn Quang, Phật Siêu Nhựt Nguyệt Quang, Phật Bất Tư Nghì Quang."],["p","Quang minh ấy chiếu khắp mười phương thế giới, chúng sanh nào gặp được quang minh ấy thì cấu uế tiêu diệt, điều lành phát sanh, thân ý hòa dịu. Nếu ở tam đồ chịu khổ cùng cực thấy được quang minh này liền được dừng khổ, mạng chung được giải thoát. Chúng sanh nào nghe được oai thần công đức quang minh này ngày đêm khen nói chí tâm không nghỉ, tùy theo ý nguyện được sanh về Cực Lạc."]]},{"t":"Phẩm Mười Ba Thọ Mạng Đại Chúng Vô Lượng","b":[["p","Này A Nan! Đức Phật Vô Lượng Thọ mạng sống trường cửu không thể tính được. Lại có vô số chúng Thanh văn thần trí thông đạt, năng lực tự tại có thể nắm tất cả thế giới trong bàn tay. Trong hàng đệ tử ta, đại Mục Kiền Liên có thần thông bậc nhất, trong một ngày đêm biết hết số lượng chúng sanh của tất cả tinh cầu trong đại thiên thế giới. Giả sử chúng sanh trong mười phương tất cả đều chứng quả Duyên giác, mỗi mỗi Duyên giác thọ vạn ức năm, có thần thông như Mục Kiền Liên, đem hết trí lực suốt đời cũng không tính đếm được, ngàn vạn phần cũng không bằng một số phần Thanh văn trong Phật hội kia."],["p","Ví như biển lớn sâu rộng vô biên, nếu lấy một sợi tóc chẻ làm trăm phần, tán ra thành bụi, rồi lấy một hột bụi ấy thấm một giọt nước biển, nước nơi bụi tóc ấy so với biển cả chẳng lấy gì nhiều."],["p","Này A Nan! Các vị Mục Kiền Liên thảy còn biết được số lượng, còn nước nơi bụi tóc so với biển cả không thể tính được."],["p","Thọ mạng của Phật và thọ lượng chúng Bồ Tát, Thanh văn, Thiên, Nhơn ở cõi ấy cũng như vậy, không thể lấy toán số thí dụ mà biết được."]]},{"t":"Phẩm Mười Bốn Cây Báu Khắp Nước","b":[["p","Cõi nước Cực Lạc có nhiều cây báu, có cây thuần bằng vàng, hoặc thuần bạc, lưu ly, thủy tinh, hổ phách, mỹ ngọc, mã não, hoặc do một thứ báu mà thành, hoặc do hai ba cho đến bảy báu xen nhau hiệp thành. Gốc thân cành do báu này thành, hoa lá quả do báu khác thành. Có cây gốc bằng vàng, thân bằng bạc, lưu ly làm cành, thủy tinh làm ngọn, hổ phách làm lá, mỹ ngọc làm hoa, mã não làm quả. Lại có các cây do bảy báu xen lẫn nhau làm gốc thân cành lá hoa quả. Mỗi báu có hàng hàng khác nhau, hàng hàng thẳng nhau, thân thân xây nhau, cành lá hướng nhau, hoa quả xứng nhau, màu sắc rực rỡ tươi đẹp không thể tả xiết. Khi gió lay động phát ra âm thanh vi diệu. Các hàng cây báu ấy cùng khắp trong cõi nước."]]},{"t":"Phẩm Mười Lăm Bồ Đề Đạo Tràng","b":[["p","Cây Bồ đề nơi đạo tràng cao bốn mươi vạn dặm, chu vi rộng năm ngàn do tuần, cành lá bốn phía hai mươi vạn dặm, do các báu tự nhiên hiệp thành, hoa quả sum sê chói sáng cùng khắp, lại có các ngọc ma ni hồng lục xanh trắng, và các báu quý nhất kết thành chuỗi trang hoàng các cột báu. Vàng ngọc chuông khánh treo khắp nơi. Lưới võng trân diệu trăm ngàn vạn sắc giăng mắc trên không."],["p","Vô lượng tia sáng phản chiếu lẫn nhau rất vi diệu, tất cả trang nghiêm tùy ý hiện nên. Gió nhẹ thổi đến lay động cành lá phát ra vô lượng âm thanh diệu pháp, vang khắp các cõi Phật, âm thanh du dương hòa nhã, tối thắng bậc nhất hơn các âm thanh ở mười phương thế giới."],["p","Nếu chúng sanh nào thấy được cây Bồ đề, nghe tiếng, ngửi mùi, nếm trái, chạm được ánh sáng, nghĩ đến công đức của cây thì sáu căn thanh tịnh không có não loạn, trụ vào bất thối chuyển cho đến khi thành Phật. Nếu thấy được cây ấy thì được ba nhẫn: Một là âm hưởng nhẫn, hai là nhu thuận nhẫn, ba là vô sanh pháp nhẫn."],["p","Này A Nan! Hoa quả cây cối và các chúng sanh cõi Phật ấy làm các Phật sự như vậy, là do sức oai thần, bản nguyện đầy đủ kiên cố cứu cánh của Phật Vô Lượng Thọ vậy."]]},{"t":"Phẩm Mười Sáu Nhà Cửa Lầu Gác","b":[["p","Giảng đường, tịnh xá, lầu quán, lan can nơi cõi Phật Vô Lượng Thọ cũng do bảy báu tự nhiên hóa thành. Lại có bạch châu ma ni nghiêm sức, sáng chói không bì được. Cung điện của Bồ Tát ở cũng lại như vậy. Nơi đó có chỗ giảng kinh, tụng kinh, thọ kinh, nghe kinh, đi kinh hành trên đất. Tư đạo và tọa thiền trên không trung, cũng có chỗ giảng tụng thọ thính kinh hành."],["p","Những vị tư đạo và tọa thiền là bậc đã chứng Tu đà hoàn, Tư đà hàm, A na hàm, hoặc A la hán. Vị chưa chứng A duy việt trí thì chứng A duy việt trí. Các vị ấy tự niệm đạo, thuyết đạo, hành đạo đầy đủ pháp hỷ."]]},{"t":"Phẩm Mười Bảy Suối Ao Công Đức","b":[["p","Hai bên giảng đường có ao suối chảy quanh, ngang dọc sâu cạn bằng nhau, hoặc mười hai mươi hoặc trăm ngàn do tuần, phẳng lặng thơm sạch, nước đủ tám công đức. Trên bờ có vô số cây chiên đàn hương, cây trái cát tường, hoa quả thơm tho, chiếu sáng rực rỡ. Lá dày che khắp trên ao, tỏa ra các mùi thơm, hương thơm thoảng trong gió theo nước bay xa, thế gian không ví được. Các ao bằng bảy báu, đáy bằng cát vàng, các hoa sen ưu bát la, bát đàm ma, câu vật đầu, phân đà lợi, nhiều màu rực rỡ khắp trên mặt nước."],["p","Chúng sanh muốn tắm, nếu muốn nước đến chân, đến gối, đến lưng, đến cổ hoặc muốn rưới khắp thân, muốn lạnh, muốn ấm, chảy mạnh hay từ từ, nhất nhất theo ý muốn, giúp phát giác tánh, phá mê khai ngộ, sạch sẽ yên tịnh."],["p","Cát báu dưới đáy phản chiếu khắp nơi, sóng gợn lăn tăn phát ra vô lượng âm thanh vi diệu, nào tiếng Tam Bảo, tiếng Ba la mật, tiếng chỉ tức tịch tịnh, tiếng vô sanh vô diệt, tiếng thập lực vô úy, tiếng vô tánh vô tác vô ngã, tiếng đại từ bi hỷ xả, tiếng cam lộ quán đảnh thọ vị. Khi nghe các âm thanh như vậy tâm liền thanh tịnh không còn phân biệt, chánh trực bình đẳng, thành thục căn lành. Ý muốn nghe pháp nào chỉ có pháp đó phát ra, nếu không muốn nghe nữa liền im lặng, vĩnh viễn không thối tâm Bồ Đề."],["p","Những người trong mười phương thế giới được vãng sanh đều hóa sanh từ trong hoa sen ở ao thất bảo, được thân pháp tánh, thể chất bất sanh bất diệt, không còn nghe tên khổ não khổ nạn của tam đồ. Giả dụ còn không có, huống là có khổ."],["p","Chỉ có tiếng vui thích tự nhiên, do vậy nước đó gọi là Cực Lạc."]]},{"t":"Phẩm Mười Tám Hiếm Có, Siêu Vượt Thế Gian","b":[["p","Dung sắc chúng sanh ở nước Cực Lạc lộng lẫy hơn hẳn thế gian, đồng một hình thể không có tướng sai biệt; chỉ vì thuận theo lề lối các phương khác nên có tên Thiên, Nhơn."],["p","Này A Nan! Ví như ở thế gian kẻ nghèo khổ ăn xin, đứng bên đế vương, diện mạo hình trạng há có thể sánh bằng không? Đế vương nếu so với Chuyển luân Thánh vương thì thô bỉ xấu xí như kẻ ăn xin. Chuyển luân Thánh vương oai tướng bậc nhất, nếu so với vua cung trời Đao Lợi lại càng xấu tệ. Trời Đế Thích so với cõi trời thứ sáu thua xa trăm ngàn lần."],["p","Cõi trời thứ sáu tuy dung mạo xinh đẹp ngàn vạn lần, làm sao sánh bằng dung sắc của Bồ Tát Thanh văn ở cõi Cực Lạc được."],["p","Đến như cung điện, y phục ẩm thực như là những vật ở cung trời Tha hóa tự tại. Còn như oai đức phẩm vị thần thông biến hóa của họ thì gấp trăm ngàn vạn ức lần hơn tất cả cõi nhơn thiên, không thể tính nổi được."],["p","A Nan nên biết, cõi nước Cực Lạc của Phật Vô Lượng Thọ có công đức trang nghiêm không thể nghĩ bàn như thế."]]},{"t":"Phẩm Mười Chín Thọ Dụng Đầy Đủ","b":[["p","Lại nữa, chúng sanh ở thế giới Cực Lạc, hoặc đã sanh, hoặc đang sanh, hoặc sẽ sanh đều có sắc thân xinh đẹp như vầy: hình dung tướng mạo đoan nghiêm, phước đức vô lượng, trí huệ sáng suốt, thần thông tự tại, thọ dụng phong túc, cung điện, phục sức, hương hoa, phan cái tất cả đều trang nghiêm, các sự cần dùng đều theo ý muốn. Khi muốn ăn, chén bát bằng bảy báu tự nhiên hiện ra, trăm thứ thức ăn tự nhiên sung mãn, tuy có đồ ăn nhưng không phải ăn, chỉ thấy sắc ngửi hương, ăn bằng ý tưởng. Sắc lực tăng trưởng, không có đại tiểu tiện, thân tâm nhẹ nhàng, không tham luyến hương vị, dùng rồi liền biến mất, đến giờ ăn lại hiện ra. Lại có nhiều y phục báu đẹp, giải mũ áo bằng anh lạc trăm ngàn màu sắc sáng chói vô lượng, tất cả tự nhiên mặc vào thân. Nhà cửa xứng với hình sắc. Lưới báu giăng trên không, linh báu treo khắp, đẹp đẽ lạ lùng, bóng loáng sáng ngời hết sức tráng lệ."],["p","Lầu các lan can, mái hiên điện đường, rộng hẹp vuông tròn, hoặc lớn hoặc nhỏ, hoặc giữa không trung, hoặc trên đất bằng, thanh tịnh yên ổn vi diệu an vui, tùy ý hiện đến đầy đủ."]]},{"t":"Phẩm Hai Mươi Gió Đức Mưa Hoa","b":[["p","Cõi nước đức Phật đó, đến giờ ăn gió thoảng nhẹ tự nhiên làm lay động lưới giăng và các cây báu phát ra âm thanh vi diệu, diễn nói pháp khổ, không, vô thường, vô ngã, các Ba la mật, lưu bố vạn thứ hương đức, ai nghe được rồi phiền não tập khí tự nhiên không khởi. Gió chạm vào mình an hòa dễ chịu, như vị Tỳ kheo chứng được diệt tận định."],["p","Lại thổi bảy hàng cây báu, thổi hoa tụ lại từng loại màu sắc trải khắp mặt đất, thứ lớp theo sắc không có tạp loạn, êm dịu sáng sạch như đâu la miên, chân đi lên lún sâu bốn lóng tay, khi dở chân lên lại bằng phẳng như cũ. Qua khỏi giờ ăn hoa ấy tự mất, mặt đất sạch sẽ, lại mưa hoa mới, tùy theo thời tiết rơi cùng khắp như trước không khác, như vậy sáu lần mỗi ngày đêm."]]},{"t":"Phẩm Hai Mươi Mốt Sen Báu Phật Quang","b":[["p","Lại có nhiều hoa sen báu cùng khắp cả nước, mỗi mỗi hoa báu có trăm ngàn ức cánh. Ánh sáng mỗi hoa có nhiều màu sắc, hoa xanh thì ánh sáng xanh, hoa trắng ánh sáng trắng, vàng đỏ tía huyền, màu sắc ánh sáng cũng lại như vậy. Lại có vô lượng diệu bảo, trăm ngàn ma ni lấp lánh kỳ lạ, sáng chiếu như nhật nguyệt."],["p","Hoa sen to lớn hoặc nửa do tuần, hoặc một hai ba bốn cho đến trăm ngàn do tuần. Trong mỗi hoa sen phát ra ba mươi sáu trăm ngàn ức tia sáng. Trong mỗi ánh sáng có ba mươi sáu trăm ngàn đức Phật sắc thân tử kim, tướng tốt thù đặc. Mỗi mỗi đức Phật lại phóng ra trăm ngàn hào quang chiếu khắp mười phương nói pháp vi diệu. Chư Phật ấy muốn đưa vô lượng chúng sanh đến Phật đạo."]]},{"t":"Phẩm Hai Mươi Hai Quyết Chứng Cực Quả","b":[["p","Lại này A Nan! Cõi nước đức Phật đó không có cảnh tối tăm đèn đuốc nhật nguyệt tinh tú ngày đêm, cũng không có tên năm tháng kiếp số, lại không có sự tham đắm nhà cửa, mọi nơi không có danh hiệu tiêu thức, cũng không có nhà ở riêng biệt, chỉ có sự hưởng thọ thanh tịnh an lạc tối thượng. Nếu có trai lành gái tín nào hoặc đã sanh hoặc sẽ sanh đều an trụ nơi chánh định, quyết sẽ chứng được A Nậu Đa La Tam Miệu Tam Bồ Đề."],["p","Tại sao vậy?"],["p","Nếu có tà định hay bất định thì không biết rõ đạo lý nhân quả để sanh về Cực Lạc được."]]},{"t":"Phẩm Hai Mươi Ba","b":[["p","MƯỜI PHƯƠNG CHƯ PHẬT TÁN THÁN"],["p","Lại nữa A Nan, hằng hà sa số thế giới ở phương Đông, trong mỗi thế giới có hằng sa đức Phật xuất tướng lưỡi rộng dài, phóng vô lượng quang minh nói lời thành thật, khen ngợi công đức bất khả tư nghì của đức Phật Vô Lượng Thọ. Hằng sa thế giới chư Phật ở chín phương khác, cũng đồng xưng tán như thế. Tại sao vậy?"],["p","Vì muốn chúng sanh ở các phương khác nghe danh hiệu đức Phật Vô Lượng Thọ, phát tâm thanh tịnh nhớ nghĩ thọ trì, quy y cúng dường cho đến phát một niệm tịnh tín, nếu có căn lành nào chí tâm hồi hướng, nguyện sanh về cõi Cực Lạc ấy, tùy nguyện vãng sanh, được Bất thối chuyển cho đến quả vị Vô thượng chánh đẳng Bồ đề."]]},{"t":"Phẩm Hai Mươi Bốn Ba Bậc Vãng Sanh","b":[["p","Này A Nan! Chư thiên, nhân dân ở mười phương thế giới chí tâm nguyện sanh về cõi ấy có ba hạng:"],["p","Bậc thượng phẩm là những người xuất gia, lìa tham dục làm sa môn, phát tâm Bồ đề, chuyên tâm niệm Phật A Di Đà, làm các công đức, nguyện sanh về cõi đó. Những chúng sanh này khi mạng chung, đức Phật A Di Đà cùng Thánh chúng hiện đến trước mặt, liền theo đức Phật sanh về cõi đó, tự nhiên hóa sanh trong hoa sen bảy báu, trí huệ dõng mãnh, thần thông tự tại."],["p","Này A Nan! Nếu có chúng sanh muốn hiện đời thấy Phật A Di Đà, phải phát tâm Vô thượng Bồ đề, phải luôn nhớ nghĩ cõi nước Cực Lạc, nhóm chứa được căn lành nào nên đem hồi hướng. Do thấy được Phật, nên khi sanh về nước đó được bậc Bất thối chuyển cho đến quả Vô thượng Bồ Đề."],["p","Hạng trung là những người tuy không làm sa môn, nhưng làm nhiều công đức, phát tâm Vô thượng Bồ Đề, chuyên tâm niệm Phật A Di Đà. Tuy đã làm nhiều công đức, giữ gìn trai giới, xây dựng tháp tượng, cúng dường, treo phan đốt đèn dâng cúng hoa hương, tất cả đều phải hồi hướng nguyện sanh về Cực Lạc. Khi mạng chung hóa thân đức Phật A Di Đà hiện ra đầy đủ tướng tốt quang minh như chính đức Phật cùng với đại chúng vây quanh hiện trước người đó, nhiếp thọ tiếp dẫn, liền theo hóa Phật sanh về cõi Cực Lạc, ở bậc Bất thối chuyển Vô thượng Bồ Đề, công đức trí huệ kế bậc thượng phẩm."],["p","Hạng hạ phẩm là những người giả sử không hay làm các công đức, mà đã phát tâm Vô thượng Bồ Đề, chuyên tâm niệm Phật A Di Đà, vui mừng tin sâu không chút nghi ngờ, hết lòng nguyện sanh về cõi Cực Lạc, người này mạng chung mộng thấy đức Phật cũng được vãng sanh, công đức trí huệ kế bậc trung."],["p","Nếu có chúng sanh theo pháp đại thừa, đem tâm thanh tịnh, hướng về đức Vô Lượng Thọ, niệm đến mười niệm, nguyện sanh về Cực Lạc, nghe pháp rộng sâu hiểu rốt ráo, cho đến được một niệm thanh tịnh, phát một niệm nhớ nghĩ đến đức Phật đó, người này mạng chung thấy Phật A Di Đà như trong chiêm bao, nhứt định sanh về nước Cực Lạc, được Bất thối chuyển Vô thượng Bồ Đề."],["p","Lại này A Nan! Nếu có trai lành gái tín nào nghe kinh này, thọ trì đọc tụng biên chép cúng dường, ngày đêm liên tục cầu sanh về cõi Cực Lạc, phát tâm Bồ Đề, giữ các giới cấm bền vững không phạm, lợi ích hữu tình, làm được chút điều lành gì đều ban bố cho họ khiến được an vui, hằng nhớ nghĩ đến đức Phật A Di Đà và cõi nước Cực Lạc ở phương Tây, người ấy khi mạng chung có sắc tướng trang nghiêm như Phật, sanh về cõi báu mau được nghe pháp, vĩnh viễn không thối chuyển."]]},{"t":"Phẩm Hai Mươi Lăm Chánh Nhân Vãng Sanh","b":[["p","Lại nữa A Nan! Nếu có chúng sanh muốn sanh về nước kia, tuy không siêng năng thiền định, nhưng hết lòng trì kinh giữ giới, chuyên làm điều lành, nghĩa là không giết hại sanh vật, không trộm cắp, không dâm dục, không nói dối, không thêu dệt, không nói lời hung dữ, không nói đâm thọc, không tham lam, không giận hờn, không si mê, ngày đêm nhớ nghĩ đức Phật A Di Đà ở thế giới Cực Lạc có nhiều công đức, nhiều sự trang nghiêm, chí tâm quy y đảnh lễ cúng dường; người ấy khi mạng chung không kinh sợ, tâm không rối loạn, liền được vãng sanh về cõi Cực Lạc."],["p","Nếu người quá nhiều việc không thể xuất gia, không rảnh tu trai giới, nhứt tâm thanh tịnh, lúc rảnh rỗi yên tịnh thân tâm, tuyệt dục bỏ lo lắng, từ tâm tinh tấn, không hờn giận, ganh ghét, không tham tiếc keo kiệt, không ân hận hồ nghi, hiếu thuận, trung tín, tin sâu lời Phật dạy, tin làm lành đặng phước, phụng trì các pháp như vậy không được thiếu mất, suy nghĩ chính chắn, muốn được độ thoát, ngày đêm luôn cầu nguyện được vãng sanh về cõi thanh tịnh của Phật A Di Đà, trong mười ngày mười đêm, cho đến một ngày một đêm không ngừng nghỉ, khi mạng chung được vãng sanh về cõi nước kia, tu đạo Bồ Tát. Những người vãng sanh đều được Bất thối chuyển, thân sắc đủ ba mươi hai tướng tốt, sẽ được thành Phật. Nếu muốn thành Phật ở một phương cõi nào khác, theo tâm ước nguyện tùy sự chuyên cần, sáng tối cầu đạo không ngừng nghỉ, sẽ được kết quả không mất chí nguyện."],["p","Này A Nan! Do điều lợi này nên vô lượng vô số bất khả tư nghì, vô biên thế giới chư Phật Như Lai đều xưng dương tán thán công đức Phật Vô Lượng Thọ."]]},{"t":"Phẩm Hai Mươi Sáu Lễ Cúng Nghe Pháp","b":[["p","Lại nữa A Nan! Chúng Bồ Tát ở mười phương thế giới muốn đảnh lễ Phật Vô Lượng Thọ ở thế giới Cực Lạc, đem hương hoa, tràng phan bảo cái đến chỗ Phật cung kính cúng dường, nghe giảng kinh pháp và xướng danh ca ngợi sự tuyên dương hóa đạo công đức trang nghiêm của Phật A Di Đà."],["p","Bấy giờ đức Thế Tôn nói bài tụng rằng:"],["v",["Đông phương các cõi Phật","Số nhiều như hằng sa,","Hằng sa chúng Bồ Tát,","Đến lễ Vô Lượng Thọ.","Nam Tây Bắc bốn phương","Thượng hạ cũng như vậy,","Thảy chí tâm tôn trọng","Dâng cúng các trân diệu","Phát những lời hòa nhã,","Ca ngợi đấng Tối Thắng,","Cứu cánh thần thông huệ","Chứng nhập sâu pháp môn.","Nghe được danh hiệu Phật,","An lành được lợi lớn.","Trong các sự cúng dường","Siêng tu không biếng trễ,","Quán cõi thù thắng kia","Vi diệu khó nghĩ bàn","Công đức rất trang nghiêm","Cõi Phật khác khó bằng.","Nhơn phát tâm vô thượng","Nguyện mau thành Bồ Đề.","Bấy giờ Vô Lượng Thọ","Kim dung hiện mỉm cười","Hào quang từ miệng ra","Chiếu khắp mười phương cõi,","Rồi xoay chiếu thân Ngài","Ba vòng vào đảnh Phật.","Bồ Tát thấy quang này","Liền chứng Bất thối chuyển","Tất cả chúng trong hội","Đều vui mừng hớn hở.","Lời Phật như sấm vang","Tiếng bát âm vi diệu","Bồ Tát mười phương đến","Di Đà thấu rõ tâm","Chí cầu cõi nghiêm tịnh","Thọ ký sẽ thành Phật,","Biết rõ tất cả pháp","Như mộng huyễn tiếng vang,","Trọn đầy các diệu nguyện","Quyết thành như Cực Lạc.","Biết cõi như ảnh tượng,","Phát tâm thệ nguyện lớn,","Rốt ráo hạnh Bồ tát,","Đầy đủ các công đức,","Thành đạt đạo Bồ Đề,","Thọ ký sẽ thành Phật.","Thông đạt các pháp tánh,","Hết thảy không, vô ngã,","Chuyên cầu tịnh cõi Phật","Quyết thành như Cực Lạc.","Nghe pháp vâng phụng hành,","Đạt đến chốn thanh tịnh,","Tất được Vô Lượng Tôn","Thọ ký thành chánh giác.","Thù thắng vô biên cõi,","Do nguyện lực Di Đà.","Nghe danh cầu vãnh sanh","Đến bậc Bất thối chuyển,","Lập thệ nguyện Bồ Tát,","Nguyện cõi này không khác,","Khắp độ hết thảy chúng","Đều phát tâm Bồ Đề,","Bỏ thân luân hồi rồi","Đều được lên bờ giác,","Phụng sự vạn ức Phật,","Giáo hóa khắp các cõi.","Kính vui mừng trở về","Cõi An Dưỡng Cực Lạc."]]]},{"t":"Phẩm Hai Mươi Bảy Ca Thán Phật Đức","b":[["p","Này A Nan: Bồ Tát ở cõi Cực Lạc nhờ oai thần của Phật trong khoảng bữa ăn đi lại vô biên cõi Phật khắp mười phương để cúng dường. Những hoa hương, tràng phan, đồ cúng dường, khởi tâm liền hiện đủ các thứ trân bảo thù thắng trên tay, thế gian không thể có để cúng dường chư Phật và chúng Bồ Tát. Nếu muốn rải hoa, liền trên không trung các hoa hiệp lại thành một lọng hoa tròn lớn có trăm ngàn sắc sáng, mỗi sắc có hương thơm khác nhau tỏa ngát muôn phương. Đài hoa nhỏ đủ mười do tuần, cứ vậy lớn dần trùm khắp ba ngàn thế giới, theo đó trước sau thứ lớp ẩn hiện, nếu không có ai cúng hoa mới thì hoa cũ không rơi xuống, lơ lửng trên không vang tiếng nhạc vi diệu tán thán Phật đức. Chốc lát trở về bổn quốc tụ họp tại giảng đường thất bảo nghe Phật Vô Lượng Thọ rộng giảng diệu pháp, tâm ý thông triệt vui mừng đại ngộ."],["p","Lại có gió thơm thổi hàng cây báu phát âm thanh vi diệu, vô lượng hương thơm theo gió bay khắp bốn phương theo như ý nguyện cúng dường không dứt."],["p","Chư Thiên đem trăm ngàn hoa hương, vạn thứ kỹ nhạc đến cúng dường Phật và chúng Bồ tát Thanh Văn. Chư Thiên trước sau qua lại, hớn hở vui mừng, là do sức oai thần bổn nguyện của Phật Vô Lượng Thọ, và đã từng cúng dường các đức Như Lai, có căn lành tương tục không giảm thiếu, khéo tu tập, khéo nhiếp thủ, khéo thành tựu vậy."]]},{"t":"Phẩm Hai Mươi Tám Đại Sĩ Thần Quang","b":[["p","Này A Nan: Chúng Bồ Tát tại cõi Phật đó nghe thấy hết khắp cả không gian và thời gian, biết hết tâm ý thiện ác, lời nguyện cầu khi nào được thoát ly lục đạo, được khai ngộ, được vãng sanh của chư Thiên, nhân loại cho đến các loại bò bay xuẩn động."],["p","Chúng Thanh văn ở cõi Phật kia có thân sáng tám thước, ánh sáng của Bồ Tát chiếu xa một trăm do tuần, có hai vị Bồ Tát tôn quý bậc nhất, oai thần và ánh sáng chiếu khắp ba ngàn cả ngàn thế giới."],["p","Tôn giả A Nan thưa Phật: “Bạch đức Thế Tôn! Hai vị Bồ Tát ấy danh hiệu gì?”"],["p","Phật nói: “Một vị tên là Quán Thế Âm, vị thứ hai tên là Đại Thế Chí, hai vị Bồ Tát này khi còn ở cõi Ta Bà tu hạnh Bồ Tát được sanh về cõi Cực Lạc thường ở hai bên tả hữu Phật A Di Đà. Muốn đến mười phương vô lượng cõi Phật liền đến, hiện ở thế giới này làm nhiều sự lợi lạc."],["p","Những trai lành gái tín ở thế gian nếu có tai nạn ngặt nghèo hoảng sợ, chỉ cần hướng tâm về Bồ Tát Quán Thế Âm thì không có nạn gì mà không được cứu thoát."]]},{"t":"Phẩm Hai Mươi Chín Nguyện Lực Hoằng Sâu","b":[["p","Lại này A Nan! Tất cả Bồ Tát ở cõi Phật ấy hoặc hiện tại hay vị lai đều rất rốt ráo được “Nhứt Sanh Bổ Xứ”, chỉ trừ phát đại nguyện vào trong sanh tử để độ quần sanh, làm sư tử hống, mặc áo giáp làm những công đức trang nghiêm cho thệ nguyện của mình. Tuy sanh trong đời ác ngũ trược, thị hiện đồng loại cho đến thành Phật, không thọ ác thú, sanh ở nơi nào đều biết rõ túc mạng."],["p","Ý của đức Phật Vô Lượng Thọ muốn độ thoát tất cả chúng sanh khắp mười phương thế giới sanh về cõi Cực Lạc đạt đến Niết Bàn. Đã làm Bồ Tát thì quyết chắc thành Phật. Đã thành Phật rồi trở lại giáo hóa độ thoát, triển chuyển không nghỉ. Thanh văn, Bồ Tát, chúng sanh sanh về cõi Phật đó đạt đến Niết bàn, chứng quả Phật số nhiều không thể tính được."],["p","Trong cõi Phật đó chỉ có một pháp không có tăng thêm. Vì sao vậy?"],["p","Ví như biển lớn là vua, các dòng nước chảy vào biển cả, nước trong biển ấy cũng không thêm bớt. Cõi Phật A Di Đà vĩnh viễn rộng lớn sáng đẹp an lạc hơn cả vô số cõi Phật trong mười phương. Ấy là do sự phát nguyện cầu đạo, tích công lũy đức khi còn làm Bồ Tát. Ân đức bố thí của Phật Vô Lượng Thọ khắp mười phương không cùng cực, sâu rộng không lường, không thể nói hết được."]]},{"t":"Phẩm Ba Mươi Bồ Tát Tu Trì","b":[["p","Lại này A Nan! Thiền định, trí tuệ, thần thông, oai đức các vị Bồ Tát trong cõi Phật đó đều viên mãn. Mật tạng chư Phật rất sâu xa rốt ráo sáng tỏ, điều phục các căn, thân tâm nhu nhuyến, thâm nhập chánh huệ, không còn dư tập, thật hành theo lời Phật dạy, hành Thất giác chi, tu Ngũ nhãn rõ biết chơn đế đạt cả tục đế. Nhục nhãn thì so đo, Thiên nhãn thấy thông suốt, Pháp nhãn thấy biết thanh tịnh, Huệ nhãn biết rõ chơn không, Phật nhãn đầy đủ công năng, biết rõ pháp tánh, biện tài tổng trì tự tại vô ngại, biết rõ vô biên phương tiện ở thế gian, nói đúng chơn đế, hiểu sâu nghĩa lý, cứu độ các hữu tình, diễn nói chánh pháp, vô tướng vô vi, vô phược vô thoát, vô phân biệt, xa lìa điên đảo, đối vật thọ dụng không có tư tưởng chiếm giữ, đi khắp cõi Phật không ưa không chán, không mong cầu cũng không chấp trước, cũng không có tưởng oán hận đây kia. Vì sao vậy?"],["p","Các vị Bồ Tát đối với chúng sanh có tâm đại từ bi đại lợi ích, xa lìa chấp trước, thành tựu vô lượng công đức, dùng chơn thật trí thấu rõ các pháp là như như, biết rõ phương tiện giảng giải về tứ đế, không thích học thuyết thế gian, thích luận chánh pháp, biết tất cả pháp đều không tịch, tập khí phiền não chướng và sở tri chướng đều dứt sạch, ở trong ba cõi bình đẳng siêng tu cứu cánh nhứt thừa đến bờ giải thoát, quyết dứt lưới nghi chứng vô sở đắc, dùng phương tiện trí tăng trưởng hiểu biết, an trụ thần thông được nhứt thừa Phật quả, không nhờ vào người khác."]]},{"t":"Phẩm Ba Mươi Mốt Công Đức Chơn Thật","b":[["p","Trí huệ uyên thâm như biển cả, Bồ Đề cao rộng như Tu di, thân sáng chói như nhật nguyệt, tâm trong trắng như tuyết sơn, nhẫn nhục như đất bằng, bình đẳng tất cả, thanh tịnh như nước rửa sạch trần cấu, hừng hực như lửa đốt hết phiền não, không chấp trước như gió không gì chướng ngại, pháp âm như sấm vang thức tỉnh kẻ chưa giác, mưa pháp cam lồ thấm nhuần chúng sanh, thênh thang như hư không bao dung tất cả, thanh tịnh như hoa sen lìa xa ô nhiễm, như cây ni câu che khắp rộng rãi, như chùy kim cang phá tan tà chấp, như núi Thiết vi tà ma ngoại đạo không lay chuyển được, tâm chánh trực khéo giỏi quyết định, luận pháp không chán, cầu pháp không mỏi mệt, giới như lưu ly trong ngoài sáng sạch, phàm nói điều gì đều làm cho người vui tín phục, đánh trống pháp, lập pháp tràng, sáng huệ nhựt, phá si ám, thuần tịnh ôn hòa, tịch định an nhiên, làm đại đạo sư, điều phục tự tha, dắt dẫn quần sanh, xả bỏ ái trước, xa hẳn ba độc, thung dung tự tại, nhân duyên nguyện lực phát sanh thiện căn, phá dẹp ma quân, tôn trọng cúng dường chư Phật, đèn sáng cho thế gian, ruộng phước tối thắng, an lành tột bậc, kham thọ cúng dường, hiển hách hoan hỷ, mạnh bạo không sợ sệt, thân tướng đẹp đẽ, công đức biện tài đầy đủ trang nghiêm không ai sánh được. Thường được chư Phật khen ngợi. Bồ Tát rốt ráo các Ba La mật, an trụ vào Tam ma địa bất sanh bất diệt, giáo hóa khắp nơi khác với hàng nhị thừa."],["p","A Nan! Ta nay lược nói chơn thật công đức các hàng Bồ Tát ở thế giới Cực Lạc kia tất cả đều như vậy. Nếu nói rộng ra trải trăm ngàn vạn kiếp cũng không hết được."]]},{"t":"Phẩm Ba Mươi Hai Thọ Lạc Không Cùng Tận","b":[["p","Phật bảo Di Lặc Bồ Tát và thiên, nhơn: “Công đức trí huệ của Thanh Văn, Bồ Tát ở cõi đức Phật Vô Lượng Thọ không thể nói hết được. Cõi nước Cực Lạc kia vi diệu an lạc thanh tịnh như vậy, há còn phương pháp nào hơn niệm Phật cầu sanh tịnh độ, tự nhiên thành tựu, xuất nhập cúng dường, quán kinh tu đạo, pháp hỷ vẹn toàn, trí huệ sáng suốt, tâm không thối chuyển, ý không giải đãi, ngoài hiện an nhàn, trong lại tinh tấn, dung cách trùm cả thái hư, đạt đến trung đạo, trong ngoài tương ưng, tự nhiên nghiêm chỉnh, hành động chánh trực, thân tâm khiết tịnh, không tham nhiễm ái, chí nguyện cương định, không tăng chẳng giảm, cầu đạo hòa chánh, không bị tà tâm khuynh đảo, tuân lời Phật dạy quyết không trái phạm, nếu đã quyết tâm thì phải kiên trì không nghĩ gì khác, không lo nghĩ ưu buồn, an nhiên vô vi, tâm rỗng như hư không không lập một pháp, bình thản không tham dục, trọn thành thiện nguyện, dốc lòng cầu tiến, từ bi ai mẫn, lễ nghĩa gồm đủ, sự lý viên dung, đạt đến giải thoát, tự tánh bản nhiên hoàn toàn thanh tịnh, chí nguyện vô thượng, thân tâm tịch định an lạc. Hốt nhiên tâm khai đạt lý giác ngộ triệt để, thấy được thật tướng các pháp, bản thể vũ trụ, quang sắc xen nhau tất cả chỉ là như như, biến chuyển vô cùng. Uất đơn việt thành thất bảo, nắm rõ vạn vật, sáng sạch hiển lộ tột đẹp vô cùng không gì sánh được, rõ ràng không trên dưới, thông suốt không ngằn mé. Vậy phải hết sức siêng năng tinh tấn tu tập quyết chắc được vãng sanh về cõi vô lượng thanh tịnh Phật A Di Đà, chấm dứt năm thú, đóng kín ác đạo, đạt đạo không khó, vãng sanh há lại không được sao! Cõi kia không trái lẽ, thuận theo tự nhiên, bỏ tất cả như hư không, siêng năng niệm Phật cầu sanh quyết đến Cực Lạc, thọ mạng an lạc không cùng, há lại tham đắm thế sự, toàn là vô thường, sầu khổ cả?"]]},{"t":"Phẩm Ba Mươi Ba Khuyến Dụ Sách Tấn","b":[["p","Người đời vì sự tranh đua nên sống trong cảnh thô bạo khổ cực nhọc thân làm lụng để tự cung cấp. Tôn quí ti tiện, nghèo khổ giàu sang, lớn nhỏ trai gái phải lao tâm khổ trí, suy nghĩ lo toan."],["p","Không nhà lo nhà, quyến thuộc tài vật, có hoặc không cũng lo, có rồi còn thiếu, muốn sao cho bằng người. Nên ít muốn vừa đủ. Lại còn lo sợ vô thường, nước lửa trộm cướp, oan gia trái chủ, lửa thiêu nước chìm, tiêu tan sạch sẽ, tâm ý khư khư không chịu buông xả, mạng chung hết thở, không ai tránh khỏi, nghèo giàu như nhau, sầu khổ trăm mối. Thế nên ở đời cha con anh em, vợ chồng thân thuộc nên thương kính nhau, không nên ghét giận nhau, có không nên thông cảm nhau, không nên tham tiếc, nói năng hòa nhã đừng chống đối nhau. Hễ có tranh cãi liền sanh giận dữ, thành oán thù nhiều kiếp về sau, sự việc ở đời đem nhiều khổ lụy, tuy chưa gặp phải, phải gấp có ý tưởng ngăn trừ. Con người vì ái dục nên phải sống chết qua lại sáu nẻo tự chịu khổ vui không ai thay thế được, lành dữ biến hóa theo đó đi thọ sanh không đồng, tụ họp không hạn kỳ. Lúc còn cường tráng sao không nỗ lực tu tập đợi đến lúc nào?"],["p","Người đời, không biện biệt được tốt xấu cát hung họa phước, thần trí ngu muội, lại theo các giáo điều khác, liên tiếp điên đảo, nguồn gốc vô thường mê mờ không chịu suy xét, chẳng tin kinh pháp, không biết lo xa, say mê giận hờn, tham đắm tài sắc, trọn chẳng ngừng nghỉ, thật đáng thương thay!"],["p","Đời trước ngu muội, không biết đạo đức, không ai chỉ bảo đâu có lạ gì? Sanh tử luân hồi, thiện ác báo ứng đều chẳng tin tưởng cho là không có. Tự thử nhìn lại: Nào cha khóc con, con khóc cha, anh em vợ chồng than khóc lẫn nhau, một đời sanh tử tiễn đưa thương tiếc, buồn thương trói buộc không sao giải nổi, nghĩ nhớ ân sâu không ngoài tình dục, sao chẳng suy cùng xét kỹ chuyên tâm hành đạo, khi tuổi già mạng hết không biết làm sao?"],["p","Kẻ mê thì nhiều, người ngộ đạo rất ít, phần nhiều ôm lòng giết hại, ác khí tràn đầy làm điều hư dối, trái ngược trời đất mặc tình tạo tội, khi mạng sống hết, đọa vào ác đạo không biết ngày ra. Các ngươi phải nghĩ kỹ, xa lìa điều ác siêng làm việc lành, ái dục vinh hoa không thể giữ mãi, đều phải ly biệt chẳng có vui gì!"],["p","Nên phải siêng năng tinh tấn cầu sanh về cõi An Lạc được trí huệ sáng suốt công đức thù thắng, đừng theo tâm tham dục, cô phụ kinh giới, uổng phí đời sau."]]},{"t":"Phẩm Ba Mươi Bốn Tâm Được Mở Sáng","b":[["p","Ngài Di Lặc Bồ Tát bạch rằng: “Bạch đức Thế Tôn! Lời Thế Tôn răn dạy rất sâu rất đúng, nhờ ơn đức từ bi giải thoát ưu khổ. Phật là đấng Pháp vương tôn quí siêu việt trong hàng Thánh, quang minh vô tận trí huệ không cùng, Đạo sư khắp cả trời người, ngày nay được gặp Phật lại được nghe hồng danh Vô Lượng Thọ, tâm trí được sáng tỏ rất là vui mừng”."],["p","Phật bảo Di Lặc Bồ Tát: “Kính Phật là điều đại thiện, niệm Phật quan trọng hơn, giúp cắt hết lưới nghi, dứt hết ái dục, lấp hết nguồn ác, đi khắp ba cõi không bị chướng ngại, khai thị chánh đạo, độ người chưa độ. Các ngươi phải biết chúng sanh mười phương nhiều kiếp đến nay luân chuyển trong năm đường, sầu khổ không dứt, sanh đã là khổ, già cũng khổ, bệnh càng khổ hơn, chết rất là đau khổ, hôi thúi bất tịnh không có gì vui, nên quyết cắt đứt, tẩy trừ tâm xấu, nói năng hành động thành tín trong ngoài hợp nhất, trước tự độ mình, lại ra độ người, hết lòng cầu nguyện, chứa nhóm căn lành, chỉ cần tinh tấn khó nhọc một đời ngắn ngủi, về sau được sanh về cõi Vô Lượng Thọ an vui vô cùng, vĩnh viễn dứt sạch sanh tử không còn khổ hoạn, thọ mạng ngàn vạn kiếp tự tại tùy ý. Nên phải tinh tấn cầu đạt, tâm nguyện không được nghi ngờ. Như còn chút nghi hoặc sẽ sanh về cung điện thất bảo ở biên địa của nước Cực Lạc, chịu các tai ách trải qua năm trăm năm”."],["p","Ngài Di Lặc bạch Phật: “Bạch đức Thế Tôn! Chúng con xin vâng lời Phật dạy chuyên cần tu học, y giáo phụng hành, không dám có lòng nghi ngờ”."]]},{"t":"Phẩm Ba Mươi Lăm Trược Thế Ác Khổ","b":[["p","Phật bảo Di Lặc: “Các ngươi sanh trong đời này, tâm ý chánh trực không làm điều ác, đó là có đức hạnh lớn.” Vì sao vậy?"],["p","Mười phương thế giới của chư Phật thiện nhiều ác ít rất dễ khai hóa. Chỉ có thế gian năm ác trược này rất là cực khổ."],["p","Ta nay thành Phật ở đây để giáo hóa quần sanh bỏ năm điều dữ, dứt năm sự thống khổ, lìa năm sự thiêu đốt, điều phục tâm ý khiến làm năm điều lành, phước đức được thành tựu."],["p","Những gì là năm?"],["p","Điều thứ nhất: Các loài chúng sanh ở thế gian thích làm điều ác, mạnh hiếp yếu, chèn ép nhau, tàn sát tổn hại ăn nuốt lẫn nhau, không biết làm lành để chịu hậu quả, nên có kẻ cùng khổ, cô độc, câm điếc đui ngọng, si ác ngông cuồng là do đời trước không tin đạo đức, không chịu làm lành. Những hạng tôn quí, hào phú, hiền minh, trưởng giả, trí dõng tài cao là do biết từ ái hiếu thuận, tu thiện tích đức từ đời trước."],["p","Khi còn sanh tiền đã làm sai trái, sau khi mạng chung vào chốn u minh chuyển thọ thân hình sanh vào các nẻo, nên có địa ngục, súc sanh – ví như lao ngục ở thế gian có cực hình kịch khổ – thần thức tùy tội đã tạo mà thọ mạng có dài ngắn theo nhau trả báo, tội ác chưa hết lại tiếp tục chịu tội, xoay vần nhiều kiếp không thôi rất khó giải thoát, khổ thống không thể nói hết được! Ác đạo tuần hoàn cảm ứng tự nhiên, tuy không báo ứng tức thời, nhưng thiện ác chung qui vẫn phải chịu quả báo."],["p","Điều thứ hai: Nhân loại thế gian không theo pháp luật, hoang dâm thái quá mặc tình phóng túng, trên thì không minh, tại vị không chính, hãm hại oan uổng, tổn hại trung lương, tâm miệng khác biệt, mưu toan nhiều bề, trong ngoài dối trá, giận dỗi ngu si, muốn lợi về mình, tham lam không chán, lợi hại được thua, oán giận thành thù, tan nhà mất mạng, không xét trước sau, giàu có keo kiệt không chịu bố thí, chất chứa cho đầy, nhọc tâm khổ thân, đến khi mạng chung không đem được gì, thiện ác họa phước tùy nghiệp thọ sanh, hoặc sanh vào nơi sung sướng hay vào chốn khổ độc. Thấy người làm lành lại còn hủy báng không chịu bắt chước, thường nghĩ trộm cắp, rình đoạt của người, tiêu phá hết rồi lại đi tìm nữa. Chết đọa vào ba đường ác chịu vô lượng khổ, xoay vần nhiều kiếp rất khó ra khỏi, đau khổ vô cùng."],["p","Điều thứ ba: Người đời nương nhau mà sống còn trong trời đất, thọ mạng chẳng được là bao? Kẻ bất lương tâm không chính đính, ôm lòng tà ác, luôn nghĩ dâm dục, phiền não tràn hông, thái độ tà ngụy buông lung, hao tổn tài sản, làm điều phi pháp, ai cầu xin gì cũng không chấp thuận, lại còn tụ bè kết đảng, hưng binh gây chiến đánh cướp giết hại, chiếm đoạt bức hiếp chu cấp cho vợ con, no thân hưởng lạc, khiến người chán ghét, lo lắng khổ cực, tạo nhiều tội ác, chết vào tam đồ chịu vô lượng khổ, qua lại nhiều kiếp, khó được giải thoát, khổ đau khôn xiết."],["p","Điều thứ tư: Người ta ở đời không chịu tu thiện, nói dối, nói lời hung dữ, nói đâm thọc, nói thêu dệt, ganh ghét người lành, hãm hại người hiền, bất hiếu với cha mẹ, khinh mạn sư trưởng, chẳng thành tín với bằng hữu, tự cao tự đại, cho mình có lý, cậy mình ỷ thế, lấn hiếp mọi người mong người kính nể, không biết hổ thẹn, ôm lòng kiêu mạn, khó thể giáo hóa. Nhờ chút phước đức từ đời trước, đời này làm ác phước đức mất hết, thọ mạng hết rồi, các điều ác bao vây, oán cừu dẫn dắt không sao tránh khỏi, chỉ việc tiến vào vạc lửa, thân thể tan nát, tâm thần thống khổ, bấy giờ nghĩ lại ăn năn thì đã muộn rồi!"],["p","Điều thứ năm: Người đời phóng túng lười biếng không chịu làm lành, tu sửa thân tâm; cha mẹ khuyên bảo, ngang trái chống đối như là oan gia, phụ bạc ân nghĩa không chút báo đền, phóng túng lêu lổng, rượu chè xa hoa, đần độn bướng bỉnh, chẳng chút lễ nghĩa, không thể can gián, giao tiếp lục thân quyến thuộc không chút ân tình, không nhớ ơn cha mẹ, không đoái nghĩa thầy trò bằng hữu, chỉ lo cho tự thân, không được một điều lành, không tin Phật pháp, không tin sanh tử thiện ác, muốn hại hiền nhân, phá hoại Phật pháp, ngu si mông muội tự cho thông minh, không biết từ đâu sanh đến, chết sẽ đi về đâu, bất nhơn bất thuận lại muốn trường thọ. Thương xót khuyên bảo lại không chịu nghe, khô hơi khản tiếng cũng thành vô ích. Tâm ý cố chấp không chịu thấu hiểu. Mạng chung cận kề hối tiếc đã không tu thiện, đến khi nhắm mắt ăn năn hối hận sao còn kịp nữa!"],["p","Trong vũ trụ, năm đường phân minh, thiện ác báo ứng họa phước đành rành, thân tự chịu lấy không ai thay được."],["p","Người thiện làm lành thì từ cảnh sướng đến cõi sướng, từ sáng vào sáng. Người ác làm ác từ cảnh khổ vào cõi khổ, từ tối vào chỗ tối. Ai hay biết được? Chỉ có đức Phật biết rõ khai thị chỉ dạy, người tuân hành rất ít, nên sanh tử không thôi, ác đạo không dứt. Người đời tạo ác như thế, nên tự nhiên có ba đường ác, chịu vô lượng khổ, xoay vần nhiều kiếp không có hạn kỳ ra khỏi, khó được giải thoát đau đớn không thể nói được. Do vậy nên có ngũ ác, ngũ thống, ngũ thiêu, như lò lửa lớn thiêu đốt thân người."],["p","Nếu tự nhứt tâm giữ ý, đoan thân chánh niệm, ngôn hành tương xứng, chí tâm làm lành không làm việc ác, thì được độ thoát, đầy đủ phước đức được trường thọ đến đạo Bồ đề. Đây là năm điều đại thiện."]]},{"t":"Phẩm Ba Mươi Sáu Bao Lượt Khuyên Lơn","b":[["p","Phật bảo Di Lặc Bồ Tát: “Những ngũ ác, ngũ thống, ngũ thiêu đó chuyển tiếp cho nhau, nếu phạm tội tất phải vào ác đạo, hiện đời sẽ bị bệnh hoạn tai ương, cầu sống không được cầu chết không xong, để cho người đời thấy sự chiêu cảm đó, mạng chung đọa vào ba đường ác, thống khổ quá lắm, tự bị thiêu đốt, cùng kết oán thù tàn hại lẫn nhau."],["p","Tạo một tội nhỏ lần thành to lớn, do tham đắm tài sắc không chịu bố thí, muốn khoái lạc bản thân không chịu phản tỉnh, si ám thúc dục tranh lợi về mình, phú quí vinh hoa đương thời vừa ý, không chịu nhẫn nhịn, không chuyên tu thiện, không bao lâu uy thế theo đó tiêu diệt, nghiệp lực an bài báo ứng tự nhiên, dù có lo lắng hoảng hốt cũng phải vào ba ác đạo, xưa nay như vậy. Đau khổ lắm thay!"],["p","Các ngươi được giáo pháp của chư Phật chỉ dạy phải suy nghĩ chín chắn tự ghi nhớ kỹ, trọn đời không được biếng trễ."],["p","Kính Phật trọng hiền, lương thiện từ bi, cầu thoát ba cõi, dứt sạch gốc sanh tử, lìa hẳn lo sợ thống khổ tam đồ."],["p","Thế nào gọi là hành thiện bậc nhất?"],["p","Phải tự tịnh tâm chánh thân, tai mắt mũi miệng đều phải đoan chánh, thân tâm thanh tịnh cùng thiện tương ưng, đừng theo thị dục, không phạm điều ác, ngôn sắc hòa diệu, thân hành chuyên cần, hành vi cử chỉ bình tĩnh từ tốn, vội vàng hấp tấp không suy xét chính chắn sẽ hư hỏng hối hận về sau, uổng phí một đời”."]]},{"t":"Phẩm Ba Mươi Bảy Như Nghèo Đặng của Báu","b":[["p","Các ngươi đã trồng nhiều căn lành, phải nhẫn nhục tinh tấn, đừng phạm cấm giới, từ tâm chuyên nhứt, thanh tịnh trai giới, tu một ngày một đêm ở cõi Ta bà hơn làm lành ở cõi Vô Lượng Thọ cả trăm năm."],["p","Tại sao vậy?"],["p","Cõi nước của đức Phật đó đều hành thiện tích đức, không có một chút ác. Tu thiện ở Ta bà mười ngày đêm hơn làm lành ngàn năm ở các cõi Phật khác."],["p","Tại sao vậy?"],["p","Vì cõi nước Phật ở phương khác thì phước đức tự nhiên có, không có duyên để làm ác, chỉ có thế giới Ta bà này thiện ít ác nhiều, toàn là khổ độc chưa từng ngừng nghỉ."],["p","Ta vì thương các ngươi nên đã hết lòng chỉ dạy trao cho kinh pháp, vậy phải nhớ giữ tuân hành. Tôn ti nam nữ quyến thuộc bằng hữu chỉ bảo lẫn nhau, cùng nhau kiểm điểm, hòa thuận đạo nghĩa, hoan hỷ từ hiếu, nếu có sai phạm phải tự hối cải, bỏ ác làm lành, sáng nghe tối sửa, phụng trì kinh giới, như nghèo được của, sửa xưa tu nay, gột rửa thân tâm, tự nhiên cảm ứng được như sở nguyện. Khi Phật còn tại thế quốc ấp thôn trang đều được hóa độ, thiên hạ hòa thuận, nhật nguyệt trong sáng, mưa thuận gió hòa, tai dịch không khởi, quốc thái dân an, binh đao vô dụng, nhân đức hưng vượng, giữ gìn lễ nghĩa, nước không trộm cướp, không có oán tặc, mạnh không hiếp yếu, đều được an lành. Ta thương các ngươi còn hơn cha mẹ thương con. Ta nay làm Phật ở đời này chỉ rõ điều lành điều dữ, dứt khổ sanh tử, được năm điều thiện, lên chốn an lạc vô vi."],["p","Khi Ta nhập Niết bàn, kinh điển lần lần diệt mất, nhân dân gian trá, làm nhiều điều ác, ngũ thiêu ngũ thống, về lâu sau càng làm ác nhiều thêm nữa, các ngươi nên khuyên bảo nhau như lời Phật dạy không được tái phạm”."],["p","Ngài Di Lặc Bồ Tát chấp tay thưa rằng: “Bạch đức Thế Tôn! Người đời ác khổ như vậy, Phật đều từ bi thương xót độ thoát tất cả. Con xin nghe lời ân cần dạy bảo của Thế Tôn không dám sai trái”."]]},{"t":"Phẩm Ba Mươi Tám Lễ Phật Hiện Ánh Sáng","b":[["p","Đức Phật bảo tôn giả A Nan: “Nếu ngươi muốn thấy đức Vô Lượng Thanh Tịnh Bình Đẳng và các Bồ Tát A la hán v.v... cõi nước đó, nên đứng dậy quay mặt về phương Tây hướng mặt trời lặn, cung kính đảnh lễ xưng niệm: Nam Mô A Di Đà Phật”."],["p","Tôn giả A Nan liền từ chỗ ngồi đứng dậy mặt hướng về phương Tây, chấp tay đảnh lễ bạch rằng: “Bạch đức Thế Tôn!"],["p","Con nay nguyện được thấy đức Phật A Di Đà ở thế giới Cực Lạc, cúng dường phụng sự, vun trồng các căn lành."],["p","Khi vừa đảnh lễ liền thấy đức Phật A Di Đà, dung nhan nguy nguy, sắc tướng trang nghiêm quang minh rực rỡ, cao lớn vượt trên tất cả thế giới."],["p","Lại nghe chư Phật Như Lai khắp mười phương thế giới xưng dương tán thán vô lượng công đức vô ngại vô cùng của đức Phật A Di Đà."],["p","Tôn giả A Nan bạch Phật: “Bạch đức Thế Tôn! Cõi Phật thanh tịnh kia rất hiếm có, con nguyện mong được sanh về cõi đó”."],["p","Đức Thế Tôn nói những người được sanh về cõi đó đã từng thân cận vô lượng đức Phật, nhiều thiện căn phước đức, ngươi muốn sanh về cõi đó thì phải nhứt tâm quy y mong cầu."],["p","Vừa nói lời ấy xong, trên tay đức Phật A Di Đà liền phóng ra vô lượng tia sáng chiếu khắp thế giới chư Phật, cõi nước chư Phật thảy đều hiện rõ như ở trước mắt, do quang minh thanh tịnh thù thắng của đức Phật A Di Đà, nên ở thế giới này như hắc sơn, tuyết sơn, kim cang, thiết vi các núi lớn nhỏ... sông suối, rừng cây, cung điện của trời, người, tất cả cảnh giới đều sáng rõ, như mặt trời mọc chiếu sáng khắp thế gian, cho đến địa ngục, ngạ quỷ, hang hố, thảy đều sáng rõ, đồng một màu sắc, như thời kiếp thủy tai nước tràn đầy cả, vạn vật chìm ngập, thăm thẳm mênh mông, chỉ toàn là nước; quang minh của Phật cũng chiếu khắp như vậy, tất cả quang minh của Thanh văn, Bồ Tát đều bị lu mờ bởi ánh hào quang sáng chói rực rỡ của đức Phật."],["p","Hàng tứ chúng trong đây, Thiên long, Bát bộ, người và phi nhơn v.v... đồng thấy các sự trang nghiêm của thế giới Cực Lạc."],["p","Đức Phật A Di Đà ở trên tòa cao, oai đức nguy nguy, tướng hảo quang minh."],["p","Các hàng Thanh văn, Bồ Tát cung kính vây quanh, như núi Tu Di đứng giữa biển cả. Thân Phật sáng rõ chiếu diệu thanh tịnh bình chánh, không có tạp uế và hình loại quái dị, chỉ có các thứ báu trang nghiêm, Thánh Hiền chung ở."],["p","Tôn giả A Nan và các chúng Bồ Tát v.v... đều rất vui mừng hớn hở đảnh lễ năm vóc sát đất xưng niệm Nam mô A Di Đà Tam Miệu Tam Phật Đà. Chư Thiên và chúng nhơn cho đến loài bò bay xuẩn động đều thấy hào quang ấy cả. Những kẻ bệnh khổ được hết bệnh khổ. Những kẻ sầu não được giải thoát, thảy đều có từ tâm làm lành, vui mừng sung sướng."],["p","Những nhạc khí như chuông, khánh, cầm sắt, không hầu không đánh tự trổi."],["p","Chư Thiên và nhân dân trong các cõi Phật khác đều đem hoa hương đến giữa hư không rải xuống cúng dường."],["p","Bấy giờ thế giới Cực Lạc ở phương tây cách xa cả trăm ngàn vô lượng ức cõi nước, nhờ oai lực của Phật mà thấy rõ như ở trước mắt, như được tịnh thiên nhãn thấy như khoảng tám thước. Đại chúng ở cõi Cực Lạc cũng lại như vậy, đều thấy đức Thích Ca Như Lai ở thế giới Ta bà này và chúng Tỳ kheo vây quanh nghe pháp."]]},{"t":"Phẩm Ba Mươi Chín Từ Thị Thuật Chỗ Thấy","b":[["p","Bấy giờ đức Phật bảo tôn giả A Nan và Từ Thị Bồ Tát rằng: “Các ông có thấy cung điện, lầu các, ao hồ, rừng cây khắp cả vi diệu trang nghiêm ở thế giới Cực Lạc không? Các ông có thấy chư Thiên ở cõi Dục cho đến cõi trời Sắc Cứu Cánh đem hoa hương cúng dường khắp cõi Phật không?”."],["p","Tôn giả A Nan bạch rằng: “Bạch đức Thế Tôn! Chúng con nhìn thấy”."],["p","“Các ông có nghe tiếng lớn của đức Phật A Di Đà truyền khắp tất cả thế giới để giáo hóa chúng sanh không?”"],["p","Tôn giả A Nan bạch rằng: “Bạch đức Thế Tôn! Chúng con có nghe”."],["p","Đức Phật bảo: “Các ông có thấy chúng tịnh hạnh ở cõi Cực Lạc nương nơi cung điện đi khắp mười phương cúng dường chư Phật mà không bị trở ngại không? Và thấy họ liên tục niệm Phật không? Lại có các loài chim bay giữa hư không, tiếng hót thánh thót, đó là do đức Phật biến hóa ra không?”"],["p","Ngài Từ Thị Bồ Tát bạch rằng: “Bạch đức Thế Tôn! Như lời đức Thế Tôn nói, chúng con đều thấy cả”."],["p","Đức Phật bảo Di Lặc rằng: “Nhân dân ở nước đó có thai sanh nữa, ông có thấy chăng?”"],["p","Ngài Di Lặc bạch rằng: “Bạch đức Thế Tôn! Con thấy người thế giới Cực Lạc ở trong thai như ở trong cung điện cõi Dạ Ma Thiên. Lại thấy chúng sanh ngồi kiết già ở trong hoa sen tự nhiên hóa sanh. Do nhân duyên gì nhân dân ở cõi đó có hạng thai sanh, hạng hóa sanh?”"]]},{"t":"Phẩm Bốn Mươi Biên Địa, Nghi Thành","b":[["p","Đức Phật bảo ngài Từ Thị: “Nếu có chúng sanh do tâm nghi hoặc làm các công đức, nguyện sanh về Cực Lạc, không rõ Phật trí, bất tư nghì trí bất khả xứng trí, Đại thừa quảng trí, Vô đẳng vô luân tối thượng thắng trí, đối với các trí này nghi ngờ không tin, nhưng vì tin tội phước mà tu tập hạnh lành, nguyện sanh về Cực Lạc."],["p","Lại có chúng sanh chứa nhóm thiện căn, mong cầu Phật trí, phổ biến trí, vô đẳng trí, oai đức quảng đại bất tư nghì trí, đối với căn lành không sanh lòng tin, ý chí còn do dự đối với sự vãng sanh cõi Phật thanh tịnh, không có tinh chuyên, nhưng vì liên tục nhớ nghĩ không thôi kết thành thiện nguyện cũng được vãng sanh."],["p","Do những nhân duyên đó, những hạng người này tuy được sanh về Cực Lạc, nhưng không thể đến thẳng cõi Đức Phật Vô Lượng Thọ được, chỉ đến biên giới cõi Phật, ở trong thành thất bảo thôi. Không phải Đức Phật muốn như vậy, mà vì chính họ tạo nên tâm đến đó vậy. Ở đó cũng có ao sen thất bảo, tự nhiên thọ thân, ăn uống sung sướng như cõi trời Đao Lợi, nhưng ở trong thành đó không thể ra khỏi, nhà ở trên đất, không thể tùy ý cao lớn."],["p","Ở đó năm trăm năm không thấy Phật, không nghe được pháp, không thấy Thánh chúng Bồ Tát, Thanh Văn, trí huệ không sáng suốt, biết kinh pháp lại ít, tâm không mở mang, ý không vui vẻ, nên ở đó gọi là thai sanh."],["p","Nếu có chúng sanh tin rõ Phật trí, cho đến thắng trí, đoạn trừ nghi hoặc, gieo các thiện căn làm các công đức, chí tâm hồi hướng, nên được hóa sanh ngồi kiết già trong hoa thất bảo, khoảnh khắc được thân tướng quang minh, công đức trí huệ thành tựu đầy đủ như các bậc Bồ Tát vậy."],["p","Di Lặc Bồ Tát phải biết, hạng hóa sanh đó có trí huệ thù thắng. Hạng thai sanh kia trong năm trăm năm không thấy Tam bảo, không biết phép tắc của Bồ Tát, không được tu tập công đức, không có nhân duyên cúng dường Phật Vô Lượng Thọ, phải biết hạng người này do đời trước không có trí tuệ, sanh tâm nghi hoặc mà ra."]]},{"t":"Phẩm Bốn Mươi Mốt Hoặc Tận Kiến Phật","b":[["p","Thí như Chuyển luân Thánh vương có bảy ngục báu để giam những vương tử nào mắc tội. Trong đó cũng có lầu các cung điện, màn báu, giường báu, lan can cửa sổ, giường ghế trang sức quý báu, ăn uống y phục được cấp dưỡng như Chuyển luân Thánh vương, nhưng bị trói chân bằng xích vàng, các tiểu vương tử này có thích ở nơi ấy không?"],["p","Ngài Từ Thị Bồ Tát bạch Phật: “Bạch đức Thế Tôn! Dĩ nhiên không vui thích!"],["p","Khi họ bị giam cầm không được tự do, chỉ muốn tìm đủ mọi cách để được ra khỏi ngục, lại cầu mọi thế lực cận thần giúp xin nhưng cũng không toại ý, bao giờ Chuyển luân Thánh Vương bằng lòng mới được giải thoát”."],["p","Này Di Lặc! Các chúng sanh này cũng lại như vậy. Vì có tâm nghi hoặc Phật trí, cho đến quảng đại trí, đối với thiện căn thiếu lòng tin sâu, do nghe danh hiệu Phật mà phát tâm tin thôi."],["p","Tuy sanh về cõi Cực Lạc ở trong hoa sen, nhưng không được ra khỏi hoa thai, trong đó cũng đủ vườn tược cung điện."],["p","Tại sao vậy?"],["p","Trong hoa thai đó thanh tịnh không có uế ác, nhưng trong năm trăm năm không thấy Tam Bảo, không được cúng dường phụng sự chư Phật, xa lìa tất cả thiện căn thù thắng, do nỗi khổ đó nên không vui thích."],["p","Nếu như những chúng sanh này biết được tội đời trước, hết lòng ăn năn tự trách cầu được ra khỏi thai hoa, khi đã hết nghiệp rồi mới được ra khỏi, thẳng đến chỗ của Đức Phật Vô Lượng Thọ, được nghe kinh pháp, lâu sau cũng được giải ngộ hoan hỷ, cũng được đi khắp cúng dường vô số vô lượng chư Phật, tu tập các công đức."],["p","Này A Dật Đa! Phải biết rằng tâm nghi hoặc tổn hại rất lớn, mất lợi ích lớn đối với Bồ Tát, nên phải tin tưởng minh bạch vô thượng trí huệ của Phật."],["p","Ngài Từ Thị Bồ Tát bạch Phật: “Bạch đức Thế Tôn! Tại sao có một hạng chúng sanh ở thế giới này tuy cũng tu thiện mà không cầu vãng sanh?”"],["p","Này Từ Thị! Những chúng sanh này trí tuệ cạn cợt, phân biệt Tây phương không bằng cõi trời, do vậy không thích cầu sanh về cõi Cực Lạc."],["p","Ngài Từ Thị bạch Phật: “Bạch đức Thế Tôn! Những chúng sanh này luống dối phân biệt không cầu sanh về cõi Phật, làm sao thoát khỏi luân hồi”."],["p","Đức Phật nói rằng: “Các chúng sanh ấy có nhiều căn lành, nhưng không bỏ tâm phân biệt vọng tưởng, không cầu Phật huệ, tham đắm phước báo vui thú thế gian. Tuy cũng làm phước, nhưng chỉ cầu quả báo nhân thiên. Tuy được quả báo đầy đủ phong túc, nhưng chưa ra khỏi ngục tù tam giới."],["p","Giả sử cha mẹ, vợ con, nam nữ quyến thuộc mà không dứt bỏ dục tướng, tà kiến vọng chấp thì luôn ở trong vòng luân hồi không được tự tại. Hạng người ngu si đó không gieo căn lành, chỉ dùng thế trí biện thông thì tăng thêm tà kiến, làm sao ra khỏi đại nạn sanh tử được."],["p","Lại có chúng sanh tuy có gieo căn lành, tạo phước lớn, nhưng vẫn giữ tâm phân biệt, tình chấp sâu nặng, cũng cầu thoát luân hồi, nhưng không thoát được."],["p","Nếu đem cái trí huệ vô tướng mà làm các công đức, thân tâm thanh tịnh, xa lìa tâm phân biệt, cầu sanh về Tịnh độ cho đến quả Bồ Đề, quyết được sanh về cõi Phật, vĩnh viễn giải thoát."]]},{"t":"Phẩm Bốn Mươi Hai Bồ Tát Vãng Sanh","b":[["p","Ngài Di Lặc Bồ Tát bạch Phật rằng: “Bạch đức Thế Tôn! Hiện nay có bao nhiêu các bậc Bất thối Bồ Tát ở cõi Ta bà này và các cõi Phật khác được sanh về nước Cực Lạc?”"],["p","Này Di Lặc! Ở thế giới Ta bà này có bảy trăm hai mươi ức Bồ Tát đã từng cúng dường vô số chư Phật, làm nhiều công đức đã sanh về Cực Lạc. Các bậc Bồ Tát sơ phát tâm, tu tập công đức đã được vãng sanh số lượng không thể tính được."],["p","Không những các bậc Bồ Tát ở cõi này được vãng sanh về Cực Lạc, mà các cõi Phật khác cũng lại như vậy."],["p","Cõi nước của Đức Phật Viễn Chiếu có mười tám câu chi na do tha đại Bồ Tát sanh về cõi Cực Lạc."],["p","Cõi nước Đức Phật Bảo Tạng ở phương Đông Bắc có chín mươi ức bất thối Bồ Tát sanh về cõi Cực Lạc."],["p","Các bậc bất thối Bồ Tát ở những cõi nước Đức Phật Vô Lượng Âm, Đức Phật Quang Minh, đức Phật Long Thiên, đức Phật Thắng Lực, Đức Phật Sư Tử, Đức Phật Ly Trần, Đức Phật Đức Thủ, Đức Phật Nhân Vương, Đức Phật Hoa Tràng đã vãng sanh số lượng mười trăm ức, hoặc trăm ngàn ức cho đến vạn ức vị."],["p","Đức Phật thứ mười hai hiệu là Vô Thượng Hoa, có vô số chúng Bồ Tát ở cõi Phật đó đều ở bậc bất thối chuyển, đã sanh về cõi Cực Lạc. Các vị ấy có trí huệ dõng mãnh, từng cúng dường vô lượng chư Phật, rất mực tinh tấn, thẳng đến nhứt thừa, trong bảy ngày đêm kiên cố tu tập như pháp bằng cả trăm ngàn ức kiếp tu tập."],["p","Đức Phật thứ mười ba hiệu là Vô Úy có bảy trăm chín mươi ức đại Bồ Tát, các vị Bồ Tát thấp và chúng Tỳ kheo v.v... sanh về cõi Cực Lạc không đếm kể được."],["p","Danh hiệu của chư Phật trong mười phương thế giới và chúng Bồ Tát đã vãng sanh, chỉ nói tên thôi mãn kiếp cũng không hết."]]},{"t":"Phẩm Bốn Mươi Ba Chẳng Phải Là Tiểu Thừa","b":[["p","Này Từ Thị! Ông thấy các bậc Bồ Tát Ma Ha Tát kia được nhiều lợi ích như vậy."],["p","Nếu có trai lành gái tín nào, được nghe danh hiệu đức Phật A Di Đà sanh tâm vui mừng hớn hở chừng một niệm, quy y chiêm lễ, như thuyết tu hành, phải biết người này được lợi ích rất lớn, được nhiều công đức như đã nói ở trên, tâm không tự ti, cũng không cống cao, thành tựu thiện căn được thêm tăng trưởng, phải biết người này không phải tiểu thừa, ở trong pháp của ta được gọi là đệ tử bậc nhứt."],["p","Cho nên ta bảo ông rằng: Những Thiên, Nhơn, A tu la ở thế gian này nên phải hớn hở tin thích tu tập, sanh tâm hy hữu, nên lấy kinh này làm thầy hướng dẫn để cho vô lượng chúng sanh mau được vào bậc bất thối chuyển, thấy được cõi Cực Lạc rộng lớn trang nghiêm nhiếp thọ thù thắng, viên mãn công đức hơn cả."],["p","Nên phải tinh tấn vâng giữ pháp môn này cầu được vãng sanh, không nên sanh tâm thối thất hư ngụy, dù có vào hầm lửa lớn cũng không được nghi ngờ hối hận."],["p","Tại sao vậy? Vô lượng vô số Bồ Tát đều mong cầu trân trọng lắng nghe pháp môn vi diệu này, không có tâm sai trái."],["p","Có nhiều vị Bồ Tát muốn nghe kinh này mà còn không được. Nên các ngươi phải cầu giữ pháp môn này."]]},{"t":"Phẩm Bốn Mươi Bốn Thọ Ký Bồ Đề","b":[["p","Về đời sau đến khi chánh pháp diệt tận, nếu có chúng sanh nào đã trồng căn lành, đã từng cúng dường vô lượng chư Phật, nhờ vào oai lực của Phật Vô Lượng Thọ gia bị mới gặp được kinh pháp này, giữ gìn thọ trì sẽ được quảng đại Nhứt Thiết Trí. Ở trong kinh pháp đó hiểu rõ cặn kẽ, sẽ được nhiều hoan hỷ, nên lưu truyền cho mọi người tin theo tu tập. Các thiện nam tín nữ đối với pháp này nếu đã cầu, hiện cầu hay sẽ cầu vãng sanh đều được nhiều lợi ích."],["p","Các ông nên phải kiên định chắc chắn, trồng các căn lành, nên luôn luôn tu tập không được ngừng nghỉ nghi ngờ, chẳng vào các cõi trân bảo thành tựu lao ngục."],["p","Này A Dật Đa! Những hạng đại oai đức này thường từ nơi các pháp đại thừa khác mà được, nên đối với pháp này không chịu lóng nghe. Có đến một ức vị Bồ Tát thối chuyển bậc Vô thượng Chánh đẳng Chánh giác."],["p","Nếu có chúng sanh nào đối với kinh này viết chép cúng dường thọ trì đọc tụng, trong chút thời gian vì người diễn nói, khuyên họ lóng nghe, không sanh ưu não, cho đến ngày đêm suy nghĩ cõi Cực Lạc và công đức của Phật A Di Đà, đối với đạo vô thượng trọn không thối chuyển."],["p","Giả sử ba ngàn thế giới tràn ngập lửa lớn, người đó khi mạng chung cũng có thể vượt khỏi, sanh vào cõi nước Cực Lạc. Bởi người ấy đời quá khứ đã từng gặp Phật và được thọ ký Bồ Đề, tất cả Như Lai đồng tán thán. Vì thế nên phải chuyên tâm tin thọ, trì tụng diễn thuyết tu hành."]]},{"t":"Phẩm Bốn Mươi Lăm Chỉ Lưu Lại Một Kinh Này","b":[["p","Ta nay vì chúng sanh mà nói kinh này, khiến thấy được Đức Phật Vô Lượng Thọ và cảnh giới trang nghiêm ở cõi Cực Lạc, hễ có tâm nguyện cầu đều được như ý."],["p","Chớ để sau khi Ta diệt độ rồi sanh lòng nghi hoặc."],["p","Đời tương lai khi kinh pháp diệt tận, Ta đem lòng từ bi thương xót, đặc biệt lưu kinh này lại trong một trăm năm, chúng sanh nào gặp được kinh này tùy ý nguyện cầu đều được độ thoát."],["p","Như Lai ra đời rất khó gặp khó thấy, kinh pháp của Phật khó được khó nghe, gặp thiện tri thức nghe pháp tu hành cũng đã là khó. Nếu nghe kinh này tin thích thọ trì là điều khó trong khó, không gì khó hơn."],["p","Nếu có chúng sanh được nghe lời Phật, từ tâm thanh tịnh, hớn hở vui mừng, hoặc râu tóc dựng đứng hay mắt rơi lệ, là do đời trước từng làm Phật sự, không phải là người phàm."],["p","Nếu nghe danh hiệu Phật tâm sanh hồ nghi, đối với kinh Phật đều không tin tưởng, đó là từ ác đạo sanh ra, túc ương chưa dứt, chưa được độ thoát, nên có tâm hồ nghi, không chịu tin tưởng."]]},{"t":"Phẩm Bốn Mươi Sáu Cần Tu Kiên Trì","b":[["p","Này Di Lặc Bồ Tát! Pháp của chư Phật Như Lai vô thượng, đủ thập lực, vô úy, thậm thâm vô ngại vô trước; pháp Ba la mật của Bồ Tát cũng không dễ gặp. Nói pháp này cho người cũng khó khai thị."],["p","Người không có lòng tin sâu vững chắc cũng khó gặp được kinh pháp này."],["p","Ta nay như lý tuyên nói pháp môn “Quảng đại vi diệu nhất thiết chư Phật xưng tán” này đem giao phó cho các ông, các ông phải cẩn thận thủ hộ, làm lợi ích cho các hữu tình chìm đắm trong đêm dài, chớ để cho chúng đọa lạc trong ngũ thú chịu các khổ ách. Nên siêng tu hành, thuận theo giáo pháp của ta, phải tâm nguyện như Phật, thường nhớ ân sư, phải làm cho pháp này lưu truyền dài lâu không bị tiêu diệt, kiên cố giữ gìn không để hủy hoại vong thất, kinh pháp nhiều ít nhớ kỹ không quên, quyết được đạo quả."],["p","Pháp của Ta như vậy, làm như vậy, nói như vậy, Như Lai đã hành trì cũng theo đó mà hành trì, tu các phước thiện, cầu sanh về cõi Tịnh độ."]]},{"t":"Phẩm Bốn Mươi Bảy Phước Huệ Được Nghe","b":[["p","Bấy giờ đức Thế Tôn nói bài tụng rằng:"],["v",["Nếu xa xưa không tu phước huệ,","Thì chánh pháp này không thể nghe","Đã từng cúng dường các Như Lai","Nên hay vui mừng tin pháp này.","Kiêu mạn giải đãi và tà kiến","Pháp vi diệu Như Lai khó tin","Như người mù hằng thấy tối đen","Không thể dẫn đường cho người"]],["v",["khác Chỉ từng trước Phật trồng căn lành","Cứu đời hành thiện mới tu tập.","Nghe rồi thọ trì và biên chép","Đọc tụng tán thán và cúng dường","Như vậy nhứt tâm cầu Tịnh độ","Giá sử lửa cháy khắp ba ngàn","Nhờ oai đức Phật tất siêu việt","Quyết định vãng sanh cõi Cực Lạc","Biển trí huệ Như Lai sâu rộng","Chỉ Phật cùng Phật mới biết được","Thanh văn ức kiếp suy trí Phật","Tận hết sức cũng không thể hiểu","Công đức Như Lai Phật tự biết","Chỉ có Thế Tôn mới khai thị.","Thân người khó được, Phật khó gặp","Tín huệ nghe pháp khó trong khó","Nếu các hữu tình sắp thành Phật","Hạnh hơn Phổ Hiền lên bờ giác","Hỡi những kẻ học rộng trí cả","Nên tin lời như thật của Ta"]],["p","Diệu pháp này may phước được nghe Nên vui mừng hãy chuyên niệm"],["v",["Phật.","Thọ trì quyết thoát biển sanh tử","Phật gọi người này thật bạn lành."]]]},{"t":"Phẩm Bốn Mươi Tám Nghe Kinh Được Lợi Ích","b":[["p","Khi đức Thế Tôn nói kinh này rồi, có một vạn hai ngàn na do tha chúng sanh xa lìa trần cấu, được pháp nhãn thanh tịnh, hai mươi ức chúng sanh chứng quả A na hàm, sáu ngàn tám trăm Tỳ kheo lậu tận tâm được giải thoát, bốn mươi ức Bồ Tát được bất thối chuyển, dùng công đức hoằng thệ mà tự trang nghiêm quả Vô Thượng Bồ đề, hai mươi lăm ức chúng sanh được bất thối nhẫn, bốn vạn ức na do tha trăm ngàn chúng sanh chưa từng phát nguyện thành Phật, nay mới phát tâm gieo các căn lành, nguyện sanh về Cực Lạc, thấy Phật A Di Đà, đều sẽ vãng sanh về cõi Tịnh độ của Phật Vô Lượng Thọ, thảy đều thứ lớp thành Phật khắp các phương cùng một danh hiệu là Diệu Âm Như Lai. Lại có tám vạn câu chi na do tha hữu tình ở mười phương cõi Phật, hoặc hiện vãng sanh, hoặc sẽ vãng sanh thấy Phật A Di Đà được thọ ký pháp nhẫn thành Vô thượng Bồ Đề, các hữu tình này có túc nguyện nhân duyên với đức Phật A Di Đà."],["p","Bấy giờ đại thiên thế giới chấn động sáu cách, và hiện các hy hữu thần biến."],["p","Quang minh sáng chói chiếu khắp mười phương. Lại có chư Thiên giữa hư không tấu âm nhạc vi diệu, cho đến chư Thiên Sắc giới cũng nghe và khen chưa từng có, vô lượng hoa đẹp thơm rưới xuống."],["p","Tôn giả A Nan, Di Lặc Bồ Tát và các hàng Bồ Tát, Thanh Văn, Thiên Long, Bát bộ tất cả đại chúng nghe lời đức Phật dạy đều rất vui mừng tín thọ phụng hành."],["p","Phật nói kinh Đại Thừa Vô Lượng Thọ Trang Nghiêm Thanh Tịnh Bình Đẳng Giác."]]},{"t":"Ma Ha Bát Nhã Ba La Mật Đa Tâm Kinh","b":[["p","Quán Tự Tại Bồ Tát hành thâm Bát Nhã Ba La Mật Đa thời, chiếu kiến ngũ uẩn giai không độ nhất thiết khổ ách."],["p","Xá Lợi Tử! Sắc bất dị không, không bất dị sắc, sắc tức thị không, không tức thị sắc, thọ, tưởng, hành, thức diệc phục như thị."],["p","Xá Lợi Tử! Thị chư pháp không tướng, bất sanh, bất diệt, bất cấu, bất tịnh, bất tăng, bất giảm. Thị cố không trung vô sắc, vô thọ, tưởng, hành, thức, vô nhãn, nhĩ, tỷ, thiệt, thân, ý, vô sắc, thinh, hương, vị, xúc, pháp, vô nhãn giới, nãi chí vô ý thức giới, vô vô minh diệc vô vô minh tận, nãi chí vô lão tử diệc, vô lão tử tận, vô khổ, tập, diệt, đạo, vô trí diệc vô đắc. Dĩ vô sở đắc cố, Bồ đề tát đỏa y Bát Nhã Ba La Mật Đa cố, tâm vô quái ngại, vô quái ngại cố, vô hữu khủng bố, viễn ly điên đảo mộng tưởng cứu cánh Niết Bàn. Tam thế chư Phật y Bát Nhã Ba La Mật Đa cố, đắc a nậu đa la tam miệu tam bồ đề. Cố tri Bát Nhã Ba La Mật Đa, thị đại thần chú, thị đại minh chú, thị vô thượng chú, thị vô đẳng đẳng chú, năng trừ nhất thiết khổ, chơn thật bất hư."],["v",["Cố thuyết Bát Nhã Ba La Mật Đa chú.","Tức thuyết chú viết:"]],["p","“Yết đế yết đế, ba la yết đế, ba la tăng yết đế, bồ đề tát bà ha.” (3 lần)"]],"p":"Nghi thức hoàn kinh"},{"t":"Vãng Sanh Quyết Định Chơn Ngôn","b":[["p","Nam mô a di đa bà dạ, đa tha già đa dạ, đa địa dạ tha. A di rị đô bà tỳ, a di rị đa tất đam bà tỳ, a di rị đa tỳ ca lan đế, a di rị đa tỳ ca lan đa, dà di nị dà dà na, chỉ đa ca lệ ta bà ha. (3 lần)"]],"p":"Nghi thức hoàn kinh"},{"t":"Tán Phật A Di Đà","b":[["v",["Phật A Di Đà thân kim sắc,","Tướng tốt quang minh tự trang nghiêm","Năm Tu Di uyển chuyển bạch hào,","Bốn biển lớn trong ngần mắt biếc,","Trong hào quang hóa vô số Phật.","Vô số Bồ Tát hiện ở trong,","Bốn mươi tám nguyện độ chúng sanh,","Chín phẩm sen vàng lên giải thoát,","Quy mạng lễ A Di Đà Phật,","Ở phương tây thế giới an lành","Con nay xin phát nguyện vãng sanh,","Cúi xin đức từ bi tiếp độ."]],["v",["Nam mô Tây Phương Cực Lạc Thế Giới","Đại Từ Đại Bi A Di Đà Phật."]],["p","A Di Đà Phật. (108, 1080 hay nhiều hơn)"]],"p":"Nghi thức hoàn kinh"},{"t":"Phát Nguyện Đảnh Lễ Phật A Di Đà, Cầu Vãng Sanh Cực Lạc Quốc","b":[["p","(Đọc lời phát nguyện này trước khi đảnh lễ Phật A Di Đà.)"],["v",["Kính lạy Phật Di Đà","Con nay xin phát nguyện","Thường xuyên đảnh lễ ngài","Cho đến lúc lâm chung","Thân thể không đau bệnh. (1 lạy)"]],["v",["Kính lạy Phật Di Đà","Con nay xin phát nguyện","Thường xuyên đảnh lễ ngài","Cho đến lúc lâm chung","Tâm hồn không hôn mê. (1 lạy)"]],["v",["Kính lạy Phật Di Đà","Con nay xin phát nguyện","Thường xuyên đảnh lễ ngài","Cho đến lúc lâm chung","Không tham đắm Ngũ dục. (1 lạy)","Kính lạy Phật Di Đà","Con nay xin phát nguyện","Thường xuyên đảnh lễ ngài","Cho đến lúc lâm chung","Tâm niệm Phật Di Đà. (1 lạy)"]],["v",["Kính lạy Phật Di Đà","Con nay xin phát nguyện","Thường xuyên đảnh lễ ngài","Cho đến lúc lâm chung","Xả ly Ta Bà khổ. (1 lạy)"]],["v",["Kính lạy Phật Di Đà","Con nay xin phát nguyện","Thường xuyên đảnh lễ ngài","Cho đến lúc lâm chung","Hân nguyện về Tịnh Độ. (1 lạy)"]],["v",["Kính lạy Phật Di Đà","Con nay xin phát nguyện","Thường xuyên đảnh lễ ngài","Cho đến lúc lâm chung","Con thấy kim thân Phật. (1 lạy)","Kính lạy Phật Di Đà","Con nay xin phát nguyện","Thường xuyên đảnh lễ ngài","Cho đến lúc lâm chung","Phật phóng quang nhiếp độ. (1 lạy)"]],["v",["Kính lạy Phật Di Đà","Con nay xin phát nguyện","Thường xuyên đảnh lễ ngài","Cho đến lúc lâm chung","Liên hoa con hóa sanh. (1 lạy)"]],["v",["Kính lạy Phật Di Đà","Con nay xin phát nguyện","Thường xuyên đảnh lễ ngài","Khi vãng sanh Tịnh Độ","Hoa nở tâm khai ngộ. (1 lạy)"]],["v",["Kính lạy Phật Di Đà","Con nay xin phát nguyện","Thường xuyên đảnh lễ ngài","Khi vãng sanh Tịnh Độ","Chứng ngộ pháp Vô Sanh. (1 lạy)","Kính lạy Phật Di Đà","Con nay xin phát nguyện","Thường xuyên đảnh lễ ngài","Khi vãng sanh Tịnh Độ","Chóng viên thành toàn giác. (1 lạy)"]],["p","Nam mô Pháp Giới Tạng Thân A Di Đà"],["p","Phật. (1 lạy)"]],"p":"Nghi thức hoàn kinh"},{"t":"Phát Nguyện Vãng Sanh Tây Phương","b":[["v",["Đệ tử chúng con,","Hiện là phàm phu,","Trong vòng sanh tử,","Tội chướng sâu nặng,","Luân chuyển sáu đường,","Khổ không nói được,","Nay gặp tri thức,","Được nghe danh hiệu,","Bản nguyện công đức,","Phật A Di Đà,","Một lòng xưng niệm,","Cầu nguyện vãng sanh,","Nguyện Phật từ bi,","Xót thương chẳng bỏ,","Phóng quang nhiếp thọ,","Đệ tử chúng con,","Chưa biết Phật Thân,","Tướng tốt quang minh,","Nguyện Phật thị hiện,","Cho con được thấy,","Lại thấy tướng mầu,","Quán Âm Thế Chí,","Các chúng Bồ Tát,","Và thế giới kia,","Thanh tịnh trang nghiêm,","Vẻ đẹp quang minh,","Xin đều thấy rõ.","Con nguyện lâm chung không chướng"]],["v",["ngại, A Di Đà đến rước từ xa,","Quan Âm cam lồ rưới nơi đầu,","Thế Chí Kim đài trao đỡ gót,","Trong một sát na lìa ngũ trược,","Khoảng tay co duỗi đến Liên Trì,","Khi hoa sen nở thấy Từ Tôn,","Nghe tiếng pháp sâu lòng sáng tỏ,","Nghe xong liền ngộ vô sanh nhẫn,","Không rời an dưỡng lại Ta Bà,","Khéo đem phương tiện lợi quần sanh,","Hay lấy trần lao làm Phật sự,","Con nguyện như thế Phật chứng tri,","Kết cuộc về sau được thành tựu.","Niệm Phật,","Lạy Phật công đức thù thắng hạnh,","Vô biên thắng phước giai hồi hướng,","Phổ nguyện Pháp giới chư chúng sanh,","Tốc vãng vô lượng quang Phật sát","Nguyện tiêu tam chướng trừ phiền não.","Nguyện đắc trí huệ chơn minh liễu.","Phổ nguyện tội chướng tất tiêu trừ.","Thế thế thường hành Bồ Tát đạo","Nguyện sanh Tây Phương tịnh độ trung.","Cửu phẩm liên hoa vi phụ mẫu,","Hoa khai kiến Phật ngộ vô sanh,","Bất thối Bồ Tát vi bạn lữ,","Nguyện dĩ thử công đức,","Phổ cập ư nhất thiết","Ngã đẵng dữ chúng sanh","Giai cộng thành Phật đạo."]]],"p":"Nghi thức hoàn kinh"},{"t":"Phục Nguyện","b":[["p","Nam Mô Tây Phương Cực Lạc Thế Giới Đại Từ Đại Bi A Di Đà Phật Liên Tòa Chứng Minh."],["p","Phục Nguyện, thượng chúc Phật nhật tăng huy pháp luân thường chuyển, phong điều vũ thuận, quốc thới dân an, thế giới hòa bình chúng sanh an lạc. Đệ tử chúng con nguyện đem công đức này hồi hướng trang nghiêm Tây Phương Phật tịnh độ, trên đền bốn ơn nặng, dưới cứu khổ ba đường, xin hồi hướng oan gia trái chủ trong nhiều đời nhiều kiếp, cũng như hiện tại, hữu hình và vô hình, nếu có ai thấy nghe đều phát tâm Bồ Đề, hết một báo thân này, sanh qua cõi Cực Lạc."],["p","Đệ tử chúng con nguyện cầu Đức Phật A Di Đà chấn tích quang lâm phóng ngọc hào quang gia hộ đệ tử chúng con biết trước giờ lâm chung, thân không tật bệnh, tâm không hôn mê, nhất tâm niệm Phật, Phật và thánh chúng tay cầm đài vàng tiếp dẫn chúng con vãng sanh về tây phương Cực Lạc."],["p","Đệ tử chúng con nguyện đức Quan Thế Âm Bồ Tát thị từ chấn tích quan lâm phóng ngọc hào quang hộ đệ tử chúng con cùng tất cả chúng sanh thân tâm thường an lạc, tật bệnh tiêu trừ căn lành tăng trưởng, phước huệ trang nghiêm, xuân đa các khánh, hạ bảo bình an, thu tống tam tai đông nghinh bách phúc, một hậu đắc Di Đà thọ ký."],["p","Đệ tử chúng con nguyện đức Phật A Di Đà thụy từ phóng ngọc hào quang, tiếp dẫn chư hương linh vong linh cửu huyền thất tổ thập nhị loại cô hồn ngạ quỷ hà xa, hữu vị vô danh, hữu danh vô vị nam nữ thương vong lai đáo Phật tiền văn kinh thính pháp tốc xả mê đồ siêu sanh tịnh độ. Phổ nguyện âm siêu dương thới pháp giới chúng sanh, tình dữ vô tình, đồng sanh Cực Lạc, đồng kiến Di Đà, Đồng Ngộ Vô Sanh. Đồng thành Phật Đạo."],["p","A DI ĐÀ PHẬT."]],"p":"Nghi thức hoàn kinh"},{"t":"Tam Quy Y","b":[["p","Tự quy y Phật, xin nguyện chúng sanh, thể theo đạo cả, phát lòng vô thượng."],["p","Tự quy y Pháp, xin nguyện chúng sanh, thấu rõ kinh tạng, trí huệ như biển."],["p","Tự quy y Tăng, xin nguyện chúng sanh, thống lý đại chúng, tất cả không ngại."]],"p":"Nghi thức hoàn kinh"},{"t":"Hồi Hướng","b":[["v",["Nguyện đem công đức nầy,","Hướng về khắp tất cả,","Đệ tử và chúng sanh,","Đồng sanh về Tịnh Độ."]],["p","Nguyện đem công đức ấn tống kinh Vô Lượng Thọ này, trang nghiêm cõi Phật Tịnh Độ, trên đền bốn ơn nặng, dưới cứu khồ ba đường, xin hồi hướng đến các vị đồng tu phát tâm ấn tống kinh Vô Lượng Thọ. Nếu có ai thấy nghe, đều phát tâm Bồ Đề, hết một báo thân này đồng sanh cõi Cực Lạc."]],"p":"Nghi thức hoàn kinh"}]};
